body.script:
//
  // 🛡️ GLOBAL CRASH-PROOF ERROR BOUNDARY
  window.addEventListener('error', function(e) {
    console.warn("Handled runtime event:", e.message);
  });
  window.addEventListener('unhandledrejection', function(e) {
    console.warn("Handled async promise event:", e.reason);
  });

  const firebaseConfig = {
    apiKey: "AIzaSyBPwqgAMR4Muj41OI7UyxSAu3N8aA9tDVE",
    authDomain: "simple-q-b7ad7.firebaseapp.com",
    projectId: "simple-q-b7ad7",
    storageBucket: "simple-q-b7ad7.firebasestorage.app",
    messagingSenderId: "327539671354",
    appId: "1:327539671354:android:9afdbb9881d7d961f29003"
  };

  let db = null;
  try {
    firebase.initializeApp(firebaseConfig);
    db = firebase.firestore();

    // Pure live online real-time stream (Eliminates multi-tab & mobile IndexedDB offline locks)
    if (db && db.settings) {
      db.settings({
        experimentalAutoDetectLongPolling: true,
        merge: true
      });
    }
  } catch (err) {
    console.warn("Firebase init notice:", err);
  }

  async function ensureFirestoreConnected() {
    if (!db) return false;
    try {
      await db.enableNetwork();
    } catch(e) {}
    return true;
  }

  window.addEventListener('online', () => {
    if (db) db.enableNetwork().catch(e => {});
  });
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible' && db) {
      db.enableNetwork().catch(e => {});
    }
  });

  let tableQuestions = [
    {
      question: "According to the data discussed, how many national parks were there in India prior to the Wildlife Protection Act of 1972 (up to 1970), and how many are there currently? / ক্লাসে আলোচিত তথ্য অনুযায়ী, ১৯৭২ সালের বন্যপ্রাণী সংরক্ষণ আইনের পূর্বে (১৯৭০ সাল পর্যন্ত) ভারতে কয়টি জাতীয় উদ্যান ছিল এবং বর্তমানে মোট কয়টি জাতীয় উদ্যান রয়েছে?",
      optionA: "5 and 107 / ৫টি এবং ১০৭টি",
      optionB: "10 and 105 / ১০টি এবং ১০৫টি",
      optionC: "5 and 106 / ৫টি এবং ১০৬টি",
      optionD: "3 and 107 / ৩টি এবং ১০৭টি",
      answer: "A",
      solution: "English: Up to 1970, India had only 5 National Parks. The current total in the source is 107. | বাংলা: ১৯৭০ সাল পর্যন্ত ভারতে মাত্র ৫টি জাতীয় উদ্যান ছিল। উৎস অনুযায়ী বর্তমানে মোট ১০৭টি জাতীয় উদ্যান রয়েছে।"
    },
    {
      question: "Which of the following national parks is NOT located in the Andaman and Nicobar Islands? / নিচের কোন জাতীয় উদ্যানটি আন্দামান ও নিকোবর দ্বীপপুঞ্জে অবস্থিত নয়?",
      optionA: "Galathea Bay National Park / গালাথিয়া বে জাতীয় উদ্যান",
      optionB: "Campbell Bay National Park / ক্যাম্পবেল বে জাতীয় উদ্যান",
      optionC: "Saddle Peak National Park / স্যাডেল পিক জাতীয় উদ্যান",
      optionD: "Papikonda National Park / পাপিকোন্ডা জাতীয় উদ্যান",
      answer: "D",
      solution: "English: Papikonda National Park is not in Andaman & Nicobar; it is associated with Andhra Pradesh."
    }
  ];

  let allCloudTopics = [];
  let currentSubjectFilter = "ALL";
  let currentSearchQuery = "";
  let currentQuizData = [];
  let currentIdx = 0;
  let userAnswers = {};
  let markedForReview = new Set();
  let timerSeconds = 900;
  let timerInterval = null;
  let langMode = "both";
  let audioReadEnabled = false;
  let voiceSpeed = 1.0;
  let micEnabled = false;
  let recognition = null;
  let audioCtx = null;
  let isFetchingCloud = false;

  // Realme Buds T110 System Audio Focus Carrier Engine
  let earbudAudioEl = null;
  let earbudWavBlobUrl = null;
  let isEarbudsActive = false;
  let isActionDebouncing = false;

  // ==========================================================================
  // REALME BUDS T110 HARDWARE AVRCP BLUETOOTH ENGINE
  // ==========================================================================
  function generateSilentWavBlob(seconds = 8) {
    const sampleRate = 8000;
    const numChannels = 1;
    const numSamples = sampleRate * seconds;
    const buffer = new ArrayBuffer(44 + numSamples * 2);
    const view = new DataView(buffer);

    function writeStr(offset, str) {
      for (let i = 0; i < str.length; i++) view.setUint8(offset + i, str.charCodeAt(i));
    }

    writeStr(0, 'RIFF');
    view.setUint32(4, 36 + numSamples * 2, true);
    writeStr(8, 'WAVE');
    writeStr(12, 'fmt ');
    view.setUint32(16, 16, true);
    view.setUint16(20, 1, true); // PCM
    view.setUint16(22, numChannels, true);
    view.setUint32(24, sampleRate, true);
    view.setUint32(28, sampleRate * 2, true);
    view.setUint16(32, 2, true);
    view.setUint16(34, 16, true);
    writeStr(36, 'data');
    view.setUint32(40, numSamples * 2, true);

    // Imperceptible audio carrier dither
    for (let i = 0; i < numSamples; i++) {
      view.setInt16(44 + i * 2, (i % 2 === 0 ? 2 : -2), true);
    }

    return new Blob([buffer], { type: 'audio/wav' });
  }

  function initEarbudsEngine() {
    try {
      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      if (audioCtx.state === 'suspended') audioCtx.resume();

      if (!earbudAudioEl) {
        if (!earbudWavBlobUrl) {
          const blob = generateSilentWavBlob(8);
          earbudWavBlobUrl = URL.createObjectURL(blob);
        }

        earbudAudioEl = document.createElement('audio');
        earbudAudioEl.id = 'copypro-earbuds-carrier';
        earbudAudioEl.src = earbudWavBlobUrl;
        earbudAudioEl.loop = true;
        earbudAudioEl.volume = 0.08;
        earbudAudioEl.setAttribute('playsinline', 'true');
        earbudAudioEl.setAttribute('webkit-playsinline', 'true');
        document.body.appendChild(earbudAudioEl);

        earbudAudioEl.addEventListener('pause', () => {
          // Keep audio carrier alive so Android/Windows notification never vanishes!
          if (isEarbudsActive) {
            setTimeout(() => {
              if (earbudAudioEl && earbudAudioEl.paused) {
                earbudAudioEl.play().catch(e => {});
              }
            }, 80);
          }
        });
      }

      earbudAudioEl.play().then(() => {
        isEarbudsActive = true;
        setupMediaSession();
        updateEarbudsUI(true);
      }).catch(err => {
        console.log("Audio carrier play error:", err);
      });

      // Warm up Speech Recognition permission in background
      if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
        try {
          if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
            navigator.mediaDevices.getUserMedia({ audio: true }).then(s => {
              s.getTracks().forEach(t => t.stop());
            }).catch(e => {});
          }
        } catch(e) {}
      }
    } catch(err) {
      console.warn("Earbuds init exception:", err);
    }
  }

  function updateEarbudsUI(active) {
    const btn = document.getElementById('btn-earbuds');
    const headerBtn = document.getElementById('btn-header-earbuds');
    const statusLbl = document.getElementById('earbuds-status-lbl');
    const statusDot = document.getElementById('earbuds-status-dot');

    if (btn) {
      if (active) {
        btn.classList.add('active');
        btn.innerHTML = "🎧 Buds: ON";
      } else {
        btn.classList.remove('active');
        btn.innerHTML = "🎧 Buds: OFF";
      }
    }
    if (headerBtn) {
      if (active) {
        headerBtn.classList.add('active');
        headerBtn.innerHTML = "🎧 Buds: Ready";
      } else {
        headerBtn.classList.remove('active');
        headerBtn.innerHTML = "🎧 Buds Mode";
      }
    }
    if (statusLbl) statusLbl.innerText = active ? "Active & Ready 🟢" : "Disconnected ⚪";
    if (statusDot) statusDot.style.color = active ? "#10B981" : "#94A3B8";
  }

  let availableAudioInputs = [];
  let selectedAudioDeviceId = localStorage.getItem('copypro_selected_mic_id') || 'default';
  let activeMicStream = null;

  async function updateAudioInputDevices() {
    if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) return;
    try {
      // Prompt userMedia permission briefly if labels are empty
      try {
        const tempStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        tempStream.getTracks().forEach(t => t.stop());
      } catch(err) {}

      const devices = await navigator.mediaDevices.enumerateDevices();
      availableAudioInputs = devices.filter(d => d.kind === 'audioinput');

      const modalSelectEl = document.getElementById('earbud-mic-device-select');
      if (!modalSelectEl) return;

      modalSelectEl.innerHTML = '';

      const defaultOpt = document.createElement('option');
      defaultOpt.value = 'default';
      defaultOpt.innerText = '⚙️ Auto-Detect Default Microphone';
      if (selectedAudioDeviceId === 'default') defaultOpt.selected = true;
      modalSelectEl.appendChild(defaultOpt);

      availableAudioInputs.forEach((dev, idx) => {
        const opt = document.createElement('option');
        opt.value = dev.deviceId;
        let rawLabel = dev.label || `Microphone ${idx + 1}`;
        let lower = rawLabel.toLowerCase();

        if (lower.includes('bluetooth') || lower.includes('buds') || lower.includes('hands-free') || lower.includes('realme') || lower.includes('headset') || lower.includes('airpods') || lower.includes('wireless')) {
          opt.innerText = `🎧 ${rawLabel} (Earbuds / Bluetooth)`;
        } else {
          opt.innerText = `💻 ${rawLabel} (Laptop / PC Mic)`;
        }

        if (dev.deviceId === selectedAudioDeviceId) opt.selected = true;
        modalSelectEl.appendChild(opt);
      });
    } catch(e) {
      console.log("Device enumeration note:", e);
    }
  }

  async function setAudioInputDevice(deviceId) {
    selectedAudioDeviceId = deviceId || 'default';
    localStorage.setItem('copypro_selected_mic_id', selectedAudioDeviceId);

    try {
      if (activeMicStream) {
        activeMicStream.getTracks().forEach(t => t.stop());
        activeMicStream = null;
      }

      const constraints = {
        audio: selectedAudioDeviceId === 'default' ? true : { deviceId: { exact: selectedAudioDeviceId } }
      };

      if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        activeMicStream = await navigator.mediaDevices.getUserMedia(constraints);
      }
    } catch(e) {
      console.log("Mic switch exception:", e);
    }

    const modalSelectEl = document.getElementById('earbud-mic-device-select');
    if (modalSelectEl) modalSelectEl.value = selectedAudioDeviceId;

    let targetLabel = "Default Microphone";
    const found = availableAudioInputs.find(d => d.deviceId === selectedAudioDeviceId);
    if (found) targetLabel = found.label || "Microphone";

    showToast(`🎙️ Active Mic: ${targetLabel}`, "🎧");

    // Seamlessly restart speech recognition on the new microphone
    if (micEnabled) {
      if (recognition) { try { recognition.stop(); } catch(e){} }
      setTimeout(() => { if (micEnabled) startGoogleSpeechListener(); }, 200);
    }
  }

  function openEarbudsModal() {
    initEarbudsEngine();
    updateAudioInputDevices();
    openModal('earbuds-modal');
  }

  function toggleEarbudsMode() {
    if (isEarbudsActive) {
      isEarbudsActive = false;
      if (earbudAudioEl) try { earbudAudioEl.pause(); } catch(e){}
      updateEarbudsUI(false);
      showToast("🎧 Earbuds Mode Paused", "ℹ️");
    } else {
      initEarbudsEngine();
      showToast("🎧 Realme Buds T110 Connected!", "🎧");
    }
  }

  function setupMediaSession() {
    if (!('mediaSession' in navigator)) return;

    const currentQ = (currentQuizData && currentQuizData[currentIdx]) ? currentQuizData[currentIdx] : null;
    const titleText = currentQ ? `Q ${currentIdx + 1}/${currentQuizData.length}: ${formatDualText(currentQ.question).replace(/\n/g, ' ').substring(0, 45)}...` : "Copy Pro Quiz Session";

    try {
      navigator.mediaSession.metadata = new MediaMetadata({
        title: titleText,
        artist: "Copy Pro AI Examiner (Realme Buds T110)",
        album: "Hands-Free CBT Test",
        artwork: [
          { src: "https://cdn-icons-png.flaticon.com/512/3406/3406828.png", sizes: "96x96", type: "image/png" },
          { src: "https://cdn-icons-png.flaticon.com/512/3406/3406828.png", sizes: "512x512", type: "image/png" }
        ]
      });

      navigator.mediaSession.playbackState = "playing";

      // Keep positionState at 50% so Android OS AVRCP enables BOTH previoustrack and nexttrack on Left & Right Buds!
      if ('setPositionState' in navigator.mediaSession) {
        try {
          navigator.mediaSession.setPositionState({
            duration: 100,
            playbackRate: 1,
            position: 50
          });
        } catch(e) {}
      }

      navigator.mediaSession.setActionHandler('play', () => {
        handleEarbudDoubleTap();
      });

      navigator.mediaSession.setActionHandler('pause', () => {
        handleEarbudDoubleTap();
      });

      // Right Earbud Hold / Triple-Tap ➔ Next Question
      navigator.mediaSession.setActionHandler('nexttrack', () => {
        handleRightBudAction();
      });

      // Left Earbud Hold / Triple-Tap ➔ Previous Question
      navigator.mediaSession.setActionHandler('previoustrack', () => {
        handleLeftBudAction();
      });

      navigator.mediaSession.setActionHandler('seekforward', () => {
        handleRightBudAction();
      });

      navigator.mediaSession.setActionHandler('seekbackward', () => {
        handleLeftBudAction();
      });

      navigator.mediaSession.setActionHandler('seekto', (details) => {
        if (details && details.seekTime !== undefined) {
          if (details.seekTime < 50) handleLeftBudAction();
          else handleRightBudAction();
        } else {
          handleRightBudAction();
        }
      });
    } catch(err) {
      console.log("MediaSession handler notice:", err);
    }
  }

  function handleEarbudDoubleTap() {
    if (isActionDebouncing) return;
    isActionDebouncing = true;
    setTimeout(() => { isActionDebouncing = false; }, 260);

    triggerEarbudDiagnosticEvent("Double-Tap (Play/Pause)", "Mic ON / Voice Answer 🎙️");

    if (!micEnabled) {
      playSound('mic_on');
      showToast("🎧 Realme Buds: Mic ON 🎙️", "🎧");
      toggleGoogleMic();
    } else {
      playSound('mic_off');
      showToast("🎧 Realme Buds: Mic OFF", "🎧");
      toggleGoogleMic();
    }

    if ('vibrate' in navigator) navigator.vibrate(25);

    // Keep audio carrier alive with ultra-low latency
    setTimeout(() => {
      if (earbudAudioEl && earbudAudioEl.paused) {
        earbudAudioEl.play().catch(e => {});
      }
      if ('mediaSession' in navigator) navigator.mediaSession.playbackState = "playing";
    }, 15);
  }

  // Right Bud Long Press / Hold / Next Track ➔ Next Question ➡️
  function handleRightBudAction() {
    if (isActionDebouncing) return;
    isActionDebouncing = true;
    setTimeout(() => { isActionDebouncing = false; }, 200);

    if ('vibrate' in navigator) navigator.vibrate(35);
    triggerEarbudDiagnosticEvent("Right Bud Hold / Next Track", "Next Question ➡️");
    playSound('next');
    showToast("👉 Realme Right Bud: Next Question ➡️", "🎧");
    nextQuestion();

    setTimeout(() => {
      if (earbudAudioEl && earbudAudioEl.paused) {
        earbudAudioEl.play().catch(e => {});
      }
      if ('mediaSession' in navigator) navigator.mediaSession.playbackState = "playing";
    }, 15);
  }

  // Left Bud Long Press / Hold / Prev Track ➔ Previous Question ⬅️
  function handleLeftBudAction() {
    if (isActionDebouncing) return;
    isActionDebouncing = true;
    setTimeout(() => { isActionDebouncing = false; }, 200);

    if ('vibrate' in navigator) navigator.vibrate(35);
    triggerEarbudDiagnosticEvent("Left Bud Hold / Prev Track", "Previous Question ⬅️");
    playSound('prev');
    showToast("👈 Realme Left Bud: Previous Question ⬅️", "🎧");
    prevQuestion();

    setTimeout(() => {
      if (earbudAudioEl && earbudAudioEl.paused) {
        earbudAudioEl.play().catch(e => {});
      }
      if ('mediaSession' in navigator) navigator.mediaSession.playbackState = "playing";
    }, 15);
  }

  function triggerEarbudDiagnosticEvent(actionName, resultDesc) {
    const box = document.getElementById('earbud-diagnostic-box');
    const title = document.getElementById('earbud-diag-title');
    const desc = document.getElementById('earbud-diag-desc');
    if (!box || !title || !desc) return;

    box.style.background = "rgba(16, 185, 129, 0.22)";
    box.style.borderColor = "#10B981";
    title.style.color = "#10B981";
    title.innerText = `✅ Detected: ${actionName}`;
    desc.innerText = `Action: ${resultDesc}`;

    setTimeout(() => {
      box.style.background = "#0F1322";
      box.style.borderColor = "var(--border-color)";
      title.style.color = "var(--accent-cyan)";
      title.innerText = "👆 Touch Your Realme Earbuds Now...";
      desc.innerText = "Double-Tap: Mic | Right Hold: Next ➡️ | Left Hold: Prev ⬅️";
    }, 1800);
  }

  function testEarbudSimulation(type) {
    initEarbudsEngine();
    if (type === 'double') handleEarbudDoubleTap();
    else if (type === 'left') handleLeftBudAction();
    else handleRightBudAction();
  }

  // Latest Next-Gen High-Fidelity Phonetic Normalizer for Bengali & English
  function cleanTextForTTS(text, isBengali = false) {
    if (!text) return "";
    let t = text
      .replace(/<[^>]*>/g, ' ')
      .replace(/[\|\/\\~^•–—]/g, ' ')
      .replace(/[\*\_`#@{}\[\]\(\)"']/g, ' ')
      .replace(/[\.\-]{2,}/g, '. ');

    if (isBengali) {
      // Latest Authentic Bengali Phonetics, Math & Unit Expansions
      t = t.replace(/%/g, ' শতাংশ ')
           .replace(/&/g, ' এবং ')
           .replace(/\+/g, ' যোগ ')
           .replace(/−|-/g, ' বিয়োগ ')
           .replace(/[×\*]/g, ' গুণ ')
           .replace(/[÷\/]/g, ' ভাগ ')
           .replace(/=/g, ' সমান ')
           .replace(/≠/g, ' অসমান ')
           .replace(/≈/g, ' প্রায় সমান ')
           .replace(/°C/gi, ' ডিগ্রি সেলসিয়াস ')
           .replace(/°F/gi, ' ডিগ্রি ফারেনহাইট ')
           .replace(/km\/h/gi, ' কিলোমিটার প্রতি ঘণ্টা ')
           .replace(/m\/s\^2|m\/s2/gi, ' মিটার প্রতি সেকেন্ড স্কয়ার ')
           .replace(/m\/s/gi, ' মিটার প্রতি সেকেন্ড ')
           .replace(/₹|Rs\.|INR/gi, ' টাকা ')
           .replace(/\$/g, ' ডলার ')
           .replace(/kg/gi, ' কিলোগ্রাম ')
           .replace(/gm|g(?=\s|$)/gi, ' গ্রাম ')
           .replace(/cm/gi, ' সেন্টিমিটার ')
           .replace(/mm/gi, ' মিলিমিটার ')
           .replace(/km/gi, ' কিলোমিটার ')
           .replace(/sq\.?\s*km/gi, ' বর্গ কিলোমিটার ')
           .replace(/sq\.?\s*m/gi, ' বর্গ মিটার ');
    } else {
      // Latest Natural English Phonetics, Math & Unit Expansions
      t = t.replace(/%/g, ' percent ')
           .replace(/&/g, ' and ')
           .replace(/\+/g, ' plus ')
           .replace(/−/g, ' minus ')
           .replace(/[×\*]/g, ' times ')
           .replace(/÷/g, ' divided by ')
           .replace(/=/g, ' equals ')
           .replace(/≠/g, ' is not equal to ')
           .replace(/≈/g, ' approximately ')
           .replace(/°C/gi, ' degree Celsius ')
           .replace(/°F/gi, ' degree Fahrenheit ')
           .replace(/km\/h/gi, ' kilometers per hour ')
           .replace(/m\/s\^2|m\/s2/gi, ' meters per second squared ')
           .replace(/m\/s/gi, ' meters per second ')
           .replace(/₹|Rs\.|INR/gi, ' Rupees ')
           .replace(/\$/g, ' Dollars ')
           .replace(/kg/gi, ' kilograms ')
           .replace(/gm|g(?=\s|$)/gi, ' grams ')
           .replace(/cm/gi, ' centimeters ')
           .replace(/mm/gi, ' millimeters ')
           .replace(/km/gi, ' kilometers ')
           .replace(/sq\.?\s*km/gi, ' square kilometers ')
           .replace(/sq\.?\s*m/gi, ' square meters ');
    }

    return t.replace(/\s+/g, ' ').trim();
  }

  // Exact Copy Pro PC Studio Neural Voice Engine with Automatic Dual-Voice Switching
  function splitEnglishBengali(text) {
    if (!text) return { eng: "", bn: "" };

    // Check if text has slash delimiter " / "
    if (text.includes(" / ")) {
      const parts = text.split(" / ");
      const engParts = [], bnParts = [];
      parts.forEach(p => {
        if (/[\u0980-\u09FF]/.test(p)) bnParts.push(p.trim());
        else engParts.push(p.trim());
      });
      return { 
        eng: engParts.join(" ").trim(), 
        bn: bnParts.join(" ").trim() 
      };
    }

    // Check if text has pipe delimiter "|"
    if (text.includes("|")) {
      const parts = text.split("|");
      const engParts = [], bnParts = [];
      parts.forEach(p => {
        if (/[\u0980-\u09FF]/.test(p)) bnParts.push(p.trim());
        else engParts.push(p.trim());
      });
      return { 
        eng: engParts.join(" ").trim(), 
        bn: bnParts.join(" ").trim() 
      };
    }

    // Multiline splitting
    const lines = text.split('\n').map(l => l.trim()).filter(l => l);
    const engLines = [], bnLines = [];
    lines.forEach(line => {
      if (/[\u0980-\u09FF]/.test(line)) bnLines.push(line);
      else engLines.push(line);
    });

    return {
      eng: engLines.join(" ").trim() || (!/[\u0980-\u09FF]/.test(text) ? text : ""),
      bn: bnLines.join(" ").trim() || (/[\u0980-\u09FF]/.test(text) ? text : "")
    };
  }

  let cachedVoices = [];
  let ttsHeartbeat = null;

  function loadBrowserVoices() {
    if (!('speechSynthesis' in window)) return [];
    cachedVoices = window.speechSynthesis.getVoices() || [];
    return cachedVoices;
  }

  if ('speechSynthesis' in window) {
    loadBrowserVoices();
    window.speechSynthesis.onvoiceschanged = () => { loadBrowserVoices(); };
  }

  function getBestVoice(isBengali) {
    let voices = cachedVoices;
    if (!voices || !voices.length) voices = loadBrowserVoices();
    if (!voices || !voices.length) return null;

    if (isBengali) {
      // 1. Exact Copy Pro PC Studio Bengali Voice: Microsoft Tanishaa Neural
      const tanishaa = voices.find(v => (v.name || '').includes('Tanishaa'));
      if (tanishaa) return tanishaa;

      // 2. Microsoft Studio Bengali Voices: Bashkar / Nabanita / Pradeep
      const otherMsBn = voices.find(v => {
        const n = v.name || '';
        return n.includes('Bashkar') || n.includes('Nabanita') || n.includes('Pradeep');
      });
      if (otherMsBn) return otherMsBn;

      // 3. Google Studio Bengali Voice (Google বাংলা)
      const googleBn = voices.find(v => {
        const n = (v.name || '').toLowerCase();
        const l = (v.lang || '').toLowerCase();
        return (l.startsWith('bn') || n.includes('bangla') || n.includes('bengali')) && n.includes('google');
      });
      if (googleBn) return googleBn;

      // 4. Any Pure Bengali Voice
      const anyBn = voices.find(v => {
        const n = (v.name || '').toLowerCase();
        const l = (v.lang || '').toLowerCase();
        return l.startsWith('bn') || n.includes('bengali') || n.includes('bangla');
      });
      if (anyBn) return anyBn;

      return null;
    } else {
      // 1. Exact Copy Pro PC Studio English Voice: Microsoft Neerja Neural
      const neerja = voices.find(v => (v.name || '').includes('Neerja'));
      if (neerja) return neerja;

      // 2. Microsoft Studio English Voices: Aria / Jenny / Sonia / Guy
      const otherMsEn = voices.find(v => {
        const n = v.name || '';
        return n.includes('Aria') || n.includes('Jenny') || n.includes('Sonia') || n.includes('Guy');
      });
      if (otherMsEn) return otherMsEn;

      // 3. Google Studio English Voice
      const googleEn = voices.find(v => {
        const n = (v.name || '').toLowerCase();
        const l = (v.lang || '').toLowerCase();
        return n.includes('google') && (l.startsWith('en-in') || l.startsWith('en-us') || l.startsWith('en-gb') || l.startsWith('en'));
      });
      if (googleEn) return googleEn;

      // 4. Any English Voice
      const anyEn = voices.find(v => (v.lang || '').toLowerCase().startsWith('en'));
      if (anyEn) return anyEn;

      return null;
    }
  }

  let activeAudioVoice = null;

  function stopStudioVoice() {
    if (ttsHeartbeat) { clearInterval(ttsHeartbeat); ttsHeartbeat = null; }
    if ('speechSynthesis' in window) {
      try { window.speechSynthesis.cancel(); } catch(e) {}
    }
    if (activeAudioVoice) {
      try {
        activeAudioVoice.pause();
        activeAudioVoice.currentTime = 0;
      } catch(e) {}
      activeAudioVoice = null;
    }
  }

  function playBengaliGoogleAudio(text, onEnd = null) {
    if (!text || !text.trim()) { if (onEnd) onEnd(); return; }

    // Chunk long text into natural phrases under 130 chars
    const chunks = [];
    const parts = text.replace(/\s+/g, ' ').trim().split(/([।\.\?!,;:\n]+)/);
    let cur = '';
    for (let i = 0; i < parts.length; i++) {
      const seg = parts[i].trim();
      if (!seg) continue;
      if ((cur + ' ' + seg).length <= 125) {
        cur = cur ? (cur + ' ' + seg) : seg;
      } else {
        if (cur) chunks.push(cur);
        cur = seg;
      }
    }
    if (cur) chunks.push(cur);

    if (!chunks.length) { if (onEnd) onEnd(); return; }

    let chunkIdx = 0;
    function playNextChunk() {
      if (chunkIdx >= chunks.length) {
        activeAudioVoice = null;
        if (onEnd) onEnd();
        return;
      }
      const c = chunks[chunkIdx++];
      const url = `https://translate.google.com/translate_tts?ie=UTF-8&client=tw-ob&tl=bn&q=${encodeURIComponent(c)}`;
      activeAudioVoice = new Audio(url);
      activeAudioVoice.playbackRate = Math.min(voiceSpeed, 1.2);
      activeAudioVoice.onended = () => { playNextChunk(); };
      activeAudioVoice.onerror = () => { playNextChunk(); };

      const p = activeAudioVoice.play();
      if (p !== undefined) {
        p.catch(() => { playNextChunk(); });
      }
    }

    playNextChunk();
  }

  function toggleAudioRead() {
    setAudioRead(!audioReadEnabled);
  }

  function setAudioRead(enable) {
    audioReadEnabled = enable;
    const btn = document.getElementById('btn-tts');
    if (btn) {
      btn.style.color = audioReadEnabled ? "#FFFFFF" : "var(--text-main)";
      btn.style.backgroundColor = audioReadEnabled ? "#059669" : "rgba(255,255,255,0.06)";
      btn.style.borderColor = audioReadEnabled ? "#10B981" : "var(--border-color)";
      btn.innerText = audioReadEnabled ? `🔊 AI: ON [T]` : `🗣️ AI [T]`;
    }
    if (audioReadEnabled) speakCurrentQuestion();
    else stopStudioVoice();
  }

  function setVoiceSpeed(speed) {
    voiceSpeed = speed;
    const btn = document.getElementById('btn-speed');
    if (btn) btn.innerText = `⚡ ${voiceSpeed}x`;
    if (audioReadEnabled) speakCurrentQuestion();
  }

  function cycleVoiceSpeed() {
    if (voiceSpeed === 0.8) setVoiceSpeed(1.0);
    else if (voiceSpeed === 1.0) setVoiceSpeed(1.25);
    else if (voiceSpeed === 1.25) setVoiceSpeed(1.5);
    else setVoiceSpeed(0.8);
  }

  function setLanguage(mode) {
    if (['both', 'en', 'bn'].includes(mode)) {
      langMode = mode;
      const btn = document.getElementById('btn-lang');
      if (btn) {
        btn.innerText = langMode === 'both' ? "🌐 Both" : (langMode === 'en' ? "🇬🇧 Eng" : "🇧🇩 Ban");
      }
      if (currentQuizData.length) loadQuestion(currentIdx);
    }
  }

  function cycleLang() {
    if (langMode === 'both') setLanguage('en');
    else if (langMode === 'en') setLanguage('bn');
    else setLanguage('both');
  }

  function speakCurrentQuestion(overrideLang = null) {
    if (!currentQuizData[currentIdx]) return;
    stopStudioVoice();

    const q = currentQuizData[currentIdx];
    const splitQ = splitEnglishBengali(q.question);
    const letters = ["A", "B", "C", "D"];
    const optEng = [], optBn = [];

    letters.forEach((l, i) => {
      const raw = q['option' + l] || '';
      const splitO = splitEnglishBengali(raw);
      if (splitO.eng) optEng.push(`Option ${i+1}: ${cleanTextForTTS(splitO.eng, false)}`);
      else if (raw && !/[\u0980-\u09FF]/.test(raw)) optEng.push(`Option ${i+1}: ${cleanTextForTTS(raw, false)}`);

      if (splitO.bn) optBn.push(`অপশন ${i+1}: ${cleanTextForTTS(splitO.bn, true)}`);
      else if (raw && /[\u0980-\u09FF]/.test(raw)) optBn.push(`অপশন ${i+1}: ${cleanTextForTTS(raw, true)}`);
    });

    const cleanEngQ = cleanTextForTTS(splitQ.eng || (!/[\u0980-\u09FF]/.test(q.question) ? q.question : ""), false);
    const cleanBnQ = cleanTextForTTS(splitQ.bn || (/[\u0980-\u09FF]/.test(q.question) ? q.question : ""), true);

    const enVoice = getBestVoice(false);
    const bnVoice = getBestVoice(true);

    const activeLang = overrideLang || langMode;

    const textEn = (cleanEngQ || optEng.length) ? (`Question ${currentIdx + 1}. ${cleanEngQ}. ` + (optEng.length ? optEng.join(". ") + "." : "")) : "";
    const prefixBn = activeLang === 'both' ? `বাংলায় প্রশ্ন ${currentIdx + 1}` : `প্রশ্ন নম্বর ${currentIdx + 1}`;
    const textBn = (cleanBnQ || optBn.length) ? (`${prefixBn}। ${cleanBnQ}। ` + (optBn.length ? optBn.join("। ") + "।" : "")) : "";

    setTimeout(() => {
      // 1. ENGLISH ONLY
      if (activeLang === 'en') {
        if (textEn && 'speechSynthesis' in window) {
          window.speechSynthesis.resume();
          const utterEn = new SpeechSynthesisUtterance(textEn);
          utterEn.lang = 'en-IN';
          if (enVoice) utterEn.voice = enVoice;
          utterEn.rate = voiceSpeed * 1.0;
          window.speechSynthesis.speak(utterEn);
        }
        return;
      }

      // 2. BENGALI ONLY
      if (activeLang === 'bn') {
        if (!textBn) return;
        if (bnVoice && 'speechSynthesis' in window) {
          window.speechSynthesis.resume();
          const utterBn = new SpeechSynthesisUtterance(textBn);
          utterBn.lang = 'bn-IN';
          utterBn.voice = bnVoice;
          utterBn.rate = voiceSpeed * 0.96;
          window.speechSynthesis.speak(utterBn);
        } else {
          playBengaliGoogleAudio(textBn);
        }
        return;
      }

      // 3. BOTH MODE
      if (activeLang === 'both') {
        if (textEn && 'speechSynthesis' in window) {
          window.speechSynthesis.resume();
          const utterEn = new SpeechSynthesisUtterance(textEn);
          utterEn.lang = 'en-IN';
          if (enVoice) utterEn.voice = enVoice;
          utterEn.rate = voiceSpeed * 1.0;

          utterEn.onend = () => {
            if (!textBn) return;
            if (bnVoice && 'speechSynthesis' in window) {
              window.speechSynthesis.resume();
              const utterBn = new SpeechSynthesisUtterance(textBn);
              utterBn.lang = 'bn-IN';
              utterBn.voice = bnVoice;
              utterBn.rate = voiceSpeed * 0.96;
              window.speechSynthesis.speak(utterBn);
            } else {
              playBengaliGoogleAudio(textBn);
            }
          };

          utterEn.onerror = () => {
            if (textBn) {
              if (bnVoice && 'speechSynthesis' in window) {
                const utterBn = new SpeechSynthesisUtterance(textBn);
                utterBn.lang = 'bn-IN';
                utterBn.voice = bnVoice;
                window.speechSynthesis.speak(utterBn);
              } else {
                playBengaliGoogleAudio(textBn);
              }
            }
          };

          window.speechSynthesis.speak(utterEn);
        } else if (textBn) {
          if (bnVoice && 'speechSynthesis' in window) {
            const utterBn = new SpeechSynthesisUtterance(textBn);
            utterBn.lang = 'bn-IN';
            utterBn.voice = bnVoice;
            window.speechSynthesis.speak(utterBn);
          } else {
            playBengaliGoogleAudio(textBn);
          }
        }
      }
    }, 10);
  }

  function narrateExplanation(overrideLang = null) {
    if (!currentQuizData[currentIdx]) return;
    stopStudioVoice();

    const q = currentQuizData[currentIdx];
    const sol = q.solution || "No explanation provided for this question.";

    // Auto-open explanation box in UI
    const solBox = document.getElementById('sol-box');
    const lblSol = document.getElementById('lbl-sol-text');
    if (solBox && lblSol) {
      lblSol.innerText = sol;
      solBox.style.display = 'block';
    }

    const splitS = splitEnglishBengali(sol);

    const cleanEng = cleanTextForTTS(splitS.eng || (!/[\u0980-\u09FF]/.test(sol) ? sol : ""), false);
    const cleanBn = cleanTextForTTS(splitS.bn || (/[\u0980-\u09FF]/.test(sol) ? sol : ""), true);

    const enVoice = getBestVoice(false);
    const bnVoice = getBestVoice(true);

    const activeLang = overrideLang || langMode;

    const textEn = cleanEng ? `Important Details and Solution. ${cleanEng}` : "";
    const textBn = cleanBn ? `গুরুত্বপূর্ণ তথ্য ও সমাধান। ${cleanBn}` : "";

    setTimeout(() => {
      if (activeLang === 'en') {
        if (textEn && 'speechSynthesis' in window) {
          window.speechSynthesis.resume();
          const utterEn = new SpeechSynthesisUtterance(textEn);
          utterEn.lang = 'en-IN';
          if (enVoice) utterEn.voice = enVoice;
          utterEn.rate = voiceSpeed * 1.0;
          window.speechSynthesis.speak(utterEn);
        }
        return;
      }

      if (activeLang === 'bn') {
        if (!textBn) return;
        if (bnVoice && 'speechSynthesis' in window) {
          window.speechSynthesis.resume();
          const utterBn = new SpeechSynthesisUtterance(textBn);
          utterBn.lang = 'bn-IN';
          utterBn.voice = bnVoice;
          utterBn.rate = voiceSpeed * 0.96;
          window.speechSynthesis.speak(utterBn);
        } else {
          playBengaliGoogleAudio(textBn);
        }
        return;
      }

      if (activeLang === 'both') {
        if (textEn && 'speechSynthesis' in window) {
          window.speechSynthesis.resume();
          const utterEn = new SpeechSynthesisUtterance(textEn);
          utterEn.lang = 'en-IN';
          if (enVoice) utterEn.voice = enVoice;
          utterEn.rate = voiceSpeed * 1.0;

          utterEn.onend = () => {
            if (!textBn) return;
            if (bnVoice && 'speechSynthesis' in window) {
              window.speechSynthesis.resume();
              const utterBn = new SpeechSynthesisUtterance(textBn);
              utterBn.lang = 'bn-IN';
              utterBn.voice = bnVoice;
              utterBn.rate = voiceSpeed * 0.96;
              window.speechSynthesis.speak(utterBn);
            } else {
              playBengaliGoogleAudio(textBn);
            }
          };

          window.speechSynthesis.speak(utterEn);
        } else if (textBn) {
          if (bnVoice && 'speechSynthesis' in window) {
            const utterBn = new SpeechSynthesisUtterance(textBn);
            utterBn.lang = 'bn-IN';
            utterBn.voice = bnVoice;
            window.speechSynthesis.speak(utterBn);
          } else {
            playBengaliGoogleAudio(textBn);
          }
        }
      }
    }, 10);
  }

  // Google Voice Assistant with Full Hands-Free Control
  let speechRecInstance = null;

  function stopSpeechListener() {
    if (speechRecInstance) {
      speechRecInstance.onend = null;
      speechRecInstance.onerror = null;
      speechRecInstance.onresult = null;
      try { speechRecInstance.abort(); } catch(e) {}
      speechRecInstance = null;
    }
  }

  function toggleGoogleMic() {
    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
      alert("Speech Recognition is not supported by your browser. Please use Chrome or Edge!");
      return;
    }

    micEnabled = !micEnabled;
    const btn = document.getElementById('btn-mic');
    const hud = document.getElementById('voice-hud');

    if (micEnabled) {
      btn.classList.add('active');
      btn.innerText = "🎙️ Mic: ON";
      hud.style.display = "flex";
      startGoogleSpeechListener();
    } else {
      btn.classList.remove('active');
      btn.innerText = "🎙️ Mic [S]";
      hud.style.display = "none";
      stopSpeechListener();
    }
  }

  function startGoogleSpeechListener() {
    if (!micEnabled) return;
    stopSpeechListener();

    try {
      const SpeechRec = window.SpeechRecognition || window.webkitSpeechRecognition;
      if (!SpeechRec) return;

      speechRecInstance = new SpeechRec();
      speechRecInstance.continuous = false; // Discrete one-shot per command = 100% RELIABLE!
      speechRecInstance.interimResults = true;
      speechRecInstance.maxAlternatives = 1;
      speechRecInstance.lang = langMode === 'bn' ? 'bn-IN' : 'en-IN';

      let commandHandledForThisTurn = false;

      speechRecInstance.onresult = (event) => {
        if (!micEnabled || commandHandledForThisTurn) return;

        let transcript = '';
        for (let i = 0; i < event.results.length; ++i) {
          transcript += event.results[i][0].transcript;
        }
        transcript = transcript.trim();
        if (!transcript) return;

        const hudText = document.getElementById('voice-hud-text');
        if (hudText) hudText.innerText = `🎤 "${transcript}"`;

        // Check command
        const executed = handleSpokenCommand(transcript);
        if (executed) {
          commandHandledForThisTurn = true;
          // Immediately cycle to a fresh recognition turn so next command is heard instantly!
          setTimeout(() => {
            if (micEnabled) startGoogleSpeechListener();
          }, 80);
        }
      };

      speechRecInstance.onerror = (event) => {
        if (micEnabled && event.error !== 'aborted') {
          setTimeout(() => {
            if (micEnabled) startGoogleSpeechListener();
          }, 100);
        }
      };

      speechRecInstance.onend = () => {
        if (micEnabled) {
          setTimeout(() => {
            if (micEnabled) startGoogleSpeechListener();
          }, 60);
        }
      };

      speechRecInstance.start();
    } catch(e) {
      console.log("Speech start notice:", e);
      if (micEnabled) {
        setTimeout(() => {
          if (micEnabled) startGoogleSpeechListener();
        }, 200);
      }
    }
  }

  function handleSpokenCommand(text) {
    if (!text) return false;
    const t = text.toLowerCase().trim();
    if (!t) return false;

    const hudText = document.getElementById('voice-hud-text');

    function executeVoiceAction(displayMsg, soundType, actionFn) {
      if ('vibrate' in navigator) navigator.vibrate(20);
      if (hudText) hudText.innerText = displayMsg;
      if (soundType) playSound(soundType);
      actionFn();
    }

    // 1. AI Voice ON / OFF Commands
    if (t.includes('ai on') || t.includes('voice on') || t.includes('ai chalu') || t.includes('awaj on') || t.includes('audio on') || t === 'on') {
      executeVoiceAction(`🎯 Recognized: "AI Voice ON" 🔊`, 'correct', () => setAudioRead(true));
      return true;
    }
    if (t.includes('ai off') || t.includes('voice off') || t.includes('stop voice') || t.includes('stop speech') || t.includes('chup') || t.includes('band karo') || t.includes('ruk jao') || t.includes('audio off') || t === 'off' || t === 'stop') {
      executeVoiceAction(`🎯 Recognized: "AI Voice OFF" 🔇`, 'wrong', () => setAudioRead(false));
      return true;
    }

    // 2. Read Bengali Details
    if (t.includes('bangla detail') || t.includes('bangla solution') || t.includes('bengali detail') || t.includes('bengali solution') || t.includes('bangla explain') || t.includes('banglay solution') || t.includes('banglay details') || t.includes('shomadhan shonao')) {
      executeVoiceAction(`🎯 Reading Solution in Bengali 🇧🇩`, 'correct', () => narrateExplanation('bn'));
      return true;
    }

    // 3. Read English Details
    if (t.includes('english detail') || t.includes('english solution') || t.includes('english explain') || t.includes('english mein details') || t.includes('english mein solution')) {
      executeVoiceAction(`🎯 Reading Solution in English 🇬🇧`, 'correct', () => narrateExplanation('en'));
      return true;
    }

    // 4. Read Bengali Question
    if (t.includes('bangla question') || t.includes('bengali question') || t.includes('bangla proshno') || t.includes('banglay question') || t.includes('banglay bolo')) {
      executeVoiceAction(`🎯 Reading Question in Bengali 🇧🇩`, 'correct', () => speakCurrentQuestion('bn'));
      return true;
    }

    // 5. Read English Question
    if (t.includes('english question') || t.includes('english mein question') || t.includes('english bolo')) {
      executeVoiceAction(`🎯 Reading Question in English 🇬🇧`, 'correct', () => speakCurrentQuestion('en'));
      return true;
    }

    // 6. General Read Details / Solution
    if (t.includes('details') || t.includes('detail') || t.includes('solution') || t.includes('explain') || t.includes('vyakhya') || t.includes('shomadhan') || t.includes('uttar') || t.includes('bujhiye') || t.includes('dekhao') || t.includes('read sol') || t.includes('read det') || t.includes('details bolo') || t.includes('read detailes')) {
      executeVoiceAction(`🎯 Recognized: "Reading Solution & Details" 💡`, 'correct', () => narrateExplanation());
      return true;
    }

    // 7. General Read Question
    if (t.includes('read question') || t.includes('question bolo') || t.includes('question padho') || t.includes('repeat question') || t.includes('prashna bolo') || t.includes('proshno poro') || t.includes('speak question') || t.includes('read again') || t === 'repeat' || t === 'again') {
      executeVoiceAction(`🎯 Recognized: "Reading Question" 🗣️`, null, () => speakCurrentQuestion());
      return true;
    }

    // 8. Navigation Commands (Next / Previous)
    if (t.includes('next') || t.includes('agla') || t.includes('aage') || t.includes('porer') || t.includes('porertaa') || t.includes('skip') || t.includes('chalo') || t.includes('forward')) {
      executeVoiceAction(`🎯 Recognized: "Next" ➔ Next Question ➡️`, 'next', () => nextQuestion());
      return true;
    }
    if (t.includes('previous') || t.includes('prev') || t.includes('pichla') || t.includes('peeche') || t.includes('aager') || t.includes('aagertaa') || t.includes('back')) {
      executeVoiceAction(`🎯 Recognized: "Previous" ➔ Previous Question ⬅️`, 'prev', () => prevQuestion());
      return true;
    }

    // 9. Clear & Review
    if (t.includes('clear') || t.includes('reset') || t.includes('mitao') || t.includes('hatao') || t.includes('muche') || t.includes('delete answer')) {
      executeVoiceAction(`🎯 Recognized: "Clear Answer" 🧹`, 'wrong', () => clearResponse());
      return true;
    }
    if (t.includes('review') || t.includes('mark') || t.includes('star') || t.includes('mark review') || t.includes('baad mein')) {
      executeVoiceAction(`🎯 Recognized: "Mark for Review" ⭐`, 'correct', () => toggleMarkReview());
      return true;
    }

    // 10. Language Commands
    if (t.includes('english') || t.includes('eng') || t.includes('angrezi')) {
      executeVoiceAction(`🎯 Language Changed: "English" 🇬🇧`, 'correct', () => setLanguage('en'));
      return true;
    }
    if (t.includes('bengali') || t.includes('bangla')) {
      executeVoiceAction(`🎯 Language Changed: "Bengali" 🇧🇩`, 'correct', () => setLanguage('bn'));
      return true;
    }
    if (t.includes('both') || t.includes('both language') || t.includes('dono') || t.includes('ubhay')) {
      executeVoiceAction(`🎯 Language Changed: "Both (Eng + Ban)" 🌐`, 'correct', () => setLanguage('both'));
      return true;
    }
    if (t.includes('change language') || t.includes('language') || t.includes('bhasha')) {
      executeVoiceAction(`🎯 Language Changed 🌐`, 'correct', () => { cycleLang(); if (hudText) hudText.innerText = `🎯 Language Changed to ${langMode.toUpperCase()} 🌐`; });
      return true;
    }

    // 11. Voice Speed Commands
    if (t.includes('fast') || t.includes('tez') || t.includes('1.5') || t.includes('speed up')) {
      executeVoiceAction(`🎯 Speed Set: 1.5x ⚡`, 'correct', () => setVoiceSpeed(1.5));
      return true;
    }
    if (t.includes('normal speed') || t.includes('1x') || t.includes('regular')) {
      executeVoiceAction(`🎯 Speed Set: 1.0x ⚡`, 'correct', () => setVoiceSpeed(1.0));
      return true;
    }
    if (t.includes('slow') || t.includes('dheere') || t.includes('0.8')) {
      executeVoiceAction(`🎯 Speed Set: 0.8x ⚡`, 'correct', () => setVoiceSpeed(0.8));
      return true;
    }

    // 12. Submit Test Command
    if (t.includes('submit') || t.includes('finish') || t.includes('khatam') || t.includes('shesh') || t.includes('submit test')) {
      executeVoiceAction(`🎯 Recognized: "Submit Exam" 🚀`, 'correct', () => submitQuizConfirm());
      return true;
    }

    // 13. Microphone Device Voice Switcher
    if (t.includes('laptop mic') || t.includes('pc mic') || t.includes('computer mic') || t.includes('internal mic')) {
      const laptopDev = availableAudioInputs.find(d => !d.label.toLowerCase().includes('bluetooth') && !d.label.toLowerCase().includes('buds') && !d.label.toLowerCase().includes('hands-free') && !d.label.toLowerCase().includes('headset'));
      const devId = laptopDev ? laptopDev.deviceId : 'default';
      executeVoiceAction(`🎯 Mic Switched: "💻 Laptop / PC Mic"`, 'correct', () => setAudioInputDevice(devId));
      return true;
    }
    if (t.includes('buds mic') || t.includes('earbuds mic') || t.includes('bluetooth mic') || t.includes('headset mic') || t.includes('realme mic')) {
      const budsDev = availableAudioInputs.find(d => d.label.toLowerCase().includes('bluetooth') || d.label.toLowerCase().includes('buds') || d.label.toLowerCase().includes('hands-free') || d.label.toLowerCase().includes('headset') || d.label.toLowerCase().includes('realme'));
      const devId = budsDev ? budsDev.deviceId : 'default';
      executeVoiceAction(`🎯 Mic Switched: "🎧 Realme Buds / Earbuds Mic"`, 'correct', () => setAudioInputDevice(devId));
      return true;
    }
    if (t.includes('default mic') || t.includes('auto mic') || t.includes('main mic')) {
      executeVoiceAction(`🎯 Mic Switched: "⚙️ Auto-Detect Default"`, 'correct', () => setAudioInputDevice('default'));
      return true;
    }

    // 14. Option Matching
    let optIndex = -1;
    if (t.includes('option a') || t.includes('option 1') || t.includes('option one') || t.includes('answer a') || t.includes('ans a') || t.includes('pahla') || t.includes('ek') || t.includes('prothom') || t === 'a' || t === 'one' || t === '1') {
      optIndex = 0;
    } else if (t.includes('option b') || t.includes('option 2') || t.includes('option two') || t.includes('answer b') || t.includes('ans b') || t.includes('dusra') || t.includes('do') || t.includes('dui') || t.includes('ditiyo') || t === 'b' || t === 'two' || t === '2') {
      optIndex = 1;
    } else if (t.includes('option c') || t.includes('option 3') || t.includes('option three') || t.includes('answer c') || t.includes('ans c') || t.includes('teesra') || t.includes('teen') || t.includes('tin') || t.includes('tritiyo') || t === 'c' || t === 'three' || t === '3') {
      optIndex = 2;
    } else if (t.includes('option d') || t.includes('option 4') || t.includes('option four') || t.includes('answer d') || t.includes('ans d') || t.includes('choutha') || t.includes('char') || t.includes('chothurtho') || t === 'd' || t === 'four' || t === '4') {
      optIndex = 3;
    }

    // 15. Content Matching
    if (optIndex === -1 && currentQuizData[currentIdx]) {
      const q = currentQuizData[currentIdx];
      const letters = ['A', 'B', 'C', 'D'];
      letters.forEach((l, i) => {
        const val = (q['option' + l] || '').toLowerCase().trim();
        if (val && val.length > 2 && (t.includes(val) || val.includes(t))) optIndex = i;
      });
    }

    if (optIndex !== -1) {
      const letters = ['A', 'B', 'C', 'D'];
      executeVoiceAction(`🎯 Option ${letters[optIndex]} Selected: "${text}" ✓`, null, () => selectOption(optIndex));
      return true;
    }

    return false;
  }

  function formatDualText(text) {
    if (!text) return "";
    if (langMode === 'both') return text;

    const lines = text.split('\n');
    const engLines = [], bnLines = [];

    lines.forEach(l => {
      if (/[\u0980-\u09FF]/.test(l)) bnLines.push(l);
      else engLines.push(l);
    });

    if (langMode === 'en') return engLines.join('\n').trim() || text;
    if (langMode === 'bn') return bnLines.join('\n').trim() || text;
    return text;
  }

  function escapeHtml(str) {
    if (!str) return '';
    return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function escapeAttr(str) {
    if (!str) return '';
    return str.replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }

  // Full Keyboard Shortcuts Engine
  window.addEventListener('keydown', (e) => {
    const tag = e.target.tagName.toLowerCase();
    if (tag === 'input' || tag === 'textarea' || tag === 'select') return;

    if (document.getElementById('view-player').classList.contains('active')) {
      const key = e.key.toUpperCase();

      if (key === '1' || key === 'A') { e.preventDefault(); selectOption(0); }
      else if (key === '2' || key === 'B') { e.preventDefault(); selectOption(1); }
      else if (key === '3' || key === 'C') { e.preventDefault(); selectOption(2); }
      else if (key === '4' || key === 'D' && !e.ctrlKey) { e.preventDefault(); selectOption(3); }
      else if (e.key === 'ArrowRight' || e.key === ' ' || e.key === 'Enter') { e.preventDefault(); nextQuestion(); }
      else if (e.key === 'ArrowLeft') { e.preventDefault(); prevQuestion(); }
      else if (key === 'M' || key === 'R') { e.preventDefault(); toggleMarkReview(); }
      else if (key === 'C' || e.key === 'Backspace') { e.preventDefault(); clearResponse(); }
      else if (key === 'E') { e.preventDefault(); toggleSolutionView(); }
      else if (key === 'T') { e.preventDefault(); toggleAudioRead(); }
      else if (key === 'S' || e.key === 'Shift') { e.preventDefault(); toggleGoogleMic(); }
      else if (key === 'L') { e.preventDefault(); cycleLang(); }
      else if (e.key === 'Escape') { switchView('table'); }
    }
  });

  // Admin Security Functions
  let pendingAdminAction = null;
  let isFirstTimeAdminSetup = false;

  async function sha256(text) {
    const msgBuffer = new TextEncoder().encode(text);
    const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
  }

  function isAdminLoggedIn() {
    return sessionStorage.getItem('copypro_admin_auth') === 'true';
  }

  function updateAdminUIState(isLoggedIn) {
    const btnAdminToggle = document.getElementById('btn-admin-toggle');
    if (btnAdminToggle) {
      if (isLoggedIn) {
        btnAdminToggle.classList.add('active');
        btnAdminToggle.innerHTML = "🛡️ Admin: ON [Logout]";
        btnAdminToggle.title = "Click to Lock & Logout from Admin mode";
      } else {
        btnAdminToggle.classList.remove('active');
        btnAdminToggle.innerHTML = "🛡️ Admin Login 🔒";
        btnAdminToggle.title = "Click to Login as Database Admin";
      }
    }
    renderCloudDashboard(allCloudTopics);
  }

  function toggleAdminLogin() {
    if (isAdminLoggedIn()) {
      if (confirm("Logout from Admin mode? Cloud test editing will be locked.")) {
        sessionStorage.removeItem('copypro_admin_auth');
        updateAdminUIState(false);
        showToast("Admin Logged Out 🔒", "🛡️");
      }
    } else {
      requireAdminAuth(() => {
        showToast("Admin Mode Activated! 🛡️", "✅");
      });
    }
  }

  async function requireAdminAuth(actionCallback) {
    if (isAdminLoggedIn()) {
      if (typeof actionCallback === 'function') actionCallback();
      return;
    }

    pendingAdminAction = actionCallback;
    const passInput = document.getElementById('admin-pass-input');
    const errEl = document.getElementById('admin-pass-error');
    const modalTitle = document.getElementById('admin-modal-title');
    const modalDesc = document.getElementById('admin-modal-desc');
    const unlockBtn = document.getElementById('btn-admin-unlock');
    const changePinBtn = document.getElementById('btn-admin-change-pin');

    if (passInput) passInput.value = '';
    if (errEl) errEl.innerText = '⏳ Verifying database connection...';

    openModal('admin-auth-modal');

    try {
      if (!db) throw new Error("Firebase database not initialized!");
      const authDoc = await db.collection("_admin_config").doc("auth").get();
      if (!authDoc.exists || !authDoc.data() || !authDoc.data().pass_hash) {
        isFirstTimeAdminSetup = true;
        if (modalTitle) modalTitle.innerText = "🔐 Set Admin Password (Initial Setup)";
        if (modalDesc) modalDesc.innerText = "No admin password exists in Firebase database yet. Enter your Secret Master Admin Password:";
        if (passInput) passInput.placeholder = "Set New Master Admin Password...";
        if (unlockBtn) unlockBtn.innerText = "Set & Secure 🔒";
        if (errEl) errEl.innerText = "";
        if (changePinBtn) changePinBtn.style.display = "none";
      } else {
        isFirstTimeAdminSetup = false;
        if (modalTitle) modalTitle.innerText = "🔐 Admin Authentication";
        if (modalDesc) modalDesc.innerText = "Enter Cloud Database Admin Password to access Admin Tools:";
        if (passInput) passInput.placeholder = "Enter Master Admin Password...";
        if (unlockBtn) unlockBtn.innerText = "Unlock 🔓";
        if (errEl) errEl.innerText = "";
        if (changePinBtn) changePinBtn.style.display = "inline-flex";
      }
    } catch (err) {
      if (errEl) errEl.innerText = "⚠️ " + err.message;
    }

    setTimeout(() => { if (passInput) passInput.focus(); }, 150);
  }

  async function verifyAdminPassword() {
    const passInput = document.getElementById('admin-pass-input');
    const entered = (passInput ? passInput.value : '').trim();
    const errEl = document.getElementById('admin-pass-error');
    const unlockBtn = document.getElementById('btn-admin-unlock');

    if (!entered || entered.length < 4) {
      if (errEl) errEl.innerText = "❌ Password must be at least 4 characters long!";
      return;
    }

    if (unlockBtn) {
      unlockBtn.disabled = true;
      unlockBtn.innerText = "Verifying ⏳...";
    }

    try {
      if (!db) throw new Error("Firebase database not connected!");
      const enteredHash = await sha256(entered);
      const authRef = db.collection("_admin_config").doc("auth");
      const authDoc = await authRef.get();

      if (!authDoc.exists || !authDoc.data() || !authDoc.data().pass_hash || isFirstTimeAdminSetup) {
        await authRef.set({
          pass_hash: enteredHash,
          updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        sessionStorage.setItem('copypro_admin_auth', 'true');
        closeModal('admin-auth-modal');
        updateAdminUIState(true);
        showToast("Master Password Saved to Database! 🔐", "✅");
        playSound('correct');
        if (typeof pendingAdminAction === 'function') {
          const action = pendingAdminAction;
          pendingAdminAction = null;
          action();
        }
      } else {
        const dbHash = authDoc.data().pass_hash;
        if (enteredHash === dbHash) {
          sessionStorage.setItem('copypro_admin_auth', 'true');
          closeModal('admin-auth-modal');
          updateAdminUIState(true);
          showToast("Admin Verified from Cloud Database 🔓", "✅");
          playSound('correct');
          if (typeof pendingAdminAction === 'function') {
            const action = pendingAdminAction;
            pendingAdminAction = null;
            action();
          }
        } else {
          playSound('wrong');
          if (errEl) errEl.innerText = "❌ Incorrect Admin Password! Access Denied.";
          if (passInput) {
            passInput.classList.add('shake-anim');
            setTimeout(() => passInput.classList.remove('shake-anim'), 500);
          }
        }
      }
    } catch (err) {
      if (errEl) errEl.innerText = "❌ Verification error: " + err.message;
    } finally {
      if (unlockBtn) {
        unlockBtn.disabled = false;
        unlockBtn.innerText = isFirstTimeAdminSetup ? "Set & Secure 🔒" : "Unlock 🔓";
      }
    }
  }

  async function changeAdminPassword() {
    if (!db) return alert("Firebase is not connected!");
    const currentPass = prompt("Enter CURRENT Cloud Database Admin Password:");
    if (!currentPass) return;

    try {
      const currentHash = await sha256(currentPass.trim());
      const authRef = db.collection("_admin_config").doc("auth");
      const authDoc = await authRef.get();

      if (!authDoc.exists || authDoc.data().pass_hash !== currentHash) {
        alert("❌ Current password incorrect! Unauthorized.");
        return;
      }

      const newPass = prompt("Enter NEW Admin Password (At least 4 characters):");
      if (!newPass || newPass.trim().length < 4) {
        alert("❌ New password must be at least 4 characters long!");
        return;
      }

      const newHash = await sha256(newPass.trim());
      await authRef.update({
        pass_hash: newHash,
        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
      });

      alert("✅ Admin Password successfully updated in Cloud Database!");
      showToast("Password Updated in Database! 🔑", "✅");
      sessionStorage.setItem('copypro_admin_auth', 'true');
      updateAdminUIState(true);
      closeModal('admin-auth-modal');
    } catch (err) {
      alert("Error updating password: " + err.message);
    }
  }

  function showToast(msg, icon = '⚡') {
    const toast = document.getElementById('app-toast');
    const toastText = document.getElementById('app-toast-text');
    const toastIcon = document.getElementById('app-toast-icon');
    if (!toast || !toastText) return;
    toastText.innerText = msg;
    if (toastIcon) toastIcon.innerText = icon;
    toast.classList.add('active');
    setTimeout(() => { toast.classList.remove('active'); }, 2500);
  }

  function playSound(type) {
    try {
      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      if (audioCtx.state === 'suspended') audioCtx.resume();
      const now = audioCtx.currentTime;

      if (type === 'mic_on') {
        const osc1 = audioCtx.createOscillator();
        const osc2 = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc1.type = 'sine'; osc2.type = 'sine';
        osc1.frequency.setValueAtTime(523.25, now); // C5
        osc2.frequency.setValueAtTime(783.99, now + 0.05); // G5
        gain.gain.setValueAtTime(0.18, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.16);
        osc1.connect(gain); osc2.connect(gain);
        gain.connect(audioCtx.destination);
        osc1.start(now); osc2.start(now + 0.05);
        osc1.stop(now + 0.16); osc2.stop(now + 0.16);
      } else if (type === 'mic_off') {
        const osc1 = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc1.type = 'sine';
        osc1.frequency.setValueAtTime(659.25, now); // E5
        osc1.frequency.exponentialRampToValueAtTime(440.00, now + 0.12); // A4
        gain.gain.setValueAtTime(0.15, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
        osc1.connect(gain); gain.connect(audioCtx.destination);
        osc1.start(now); osc1.stop(now + 0.12);
      } else if (type === 'next') {
        const osc1 = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc1.type = 'sine';
        osc1.frequency.setValueAtTime(659.25, now); // E5
        osc1.frequency.exponentialRampToValueAtTime(987.77, now + 0.09); // B5
        gain.gain.setValueAtTime(0.16, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.14);
        osc1.connect(gain); gain.connect(audioCtx.destination);
        osc1.start(now); osc1.stop(now + 0.14);
      } else if (type === 'prev') {
        const osc1 = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc1.type = 'sine';
        osc1.frequency.setValueAtTime(783.99, now); // G5
        osc1.frequency.exponentialRampToValueAtTime(523.25, now + 0.09); // C5
        gain.gain.setValueAtTime(0.15, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.14);
        osc1.connect(gain); gain.connect(audioCtx.destination);
        osc1.start(now); osc1.stop(now + 0.14);
      } else if (type === 'correct') {
        const osc1 = audioCtx.createOscillator();
        const osc2 = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc1.type = 'sine'; osc2.type = 'triangle';
        osc1.frequency.setValueAtTime(523.25, now); // C5
        osc1.frequency.setValueAtTime(659.25, now + 0.06); // E5
        osc2.frequency.setValueAtTime(1046.50, now + 0.1); // C6
        gain.gain.setValueAtTime(0.2, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.28);
        osc1.connect(gain); osc2.connect(gain);
        gain.connect(audioCtx.destination);
        osc1.start(now); osc2.start(now + 0.08);
        osc1.stop(now + 0.28); osc2.stop(now + 0.28);
      } else if (type === 'wrong') {
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(196.00, now);
        osc.frequency.setValueAtTime(164.81, now + 0.08);
        gain.gain.setValueAtTime(0.12, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
        osc.connect(gain); gain.connect(audioCtx.destination);
        osc.start(now); osc.stop(now + 0.2);
      }
    } catch(e) {}
  }

  function switchView(viewName) {
    document.querySelectorAll('.view-section').forEach(el => el.classList.remove('active'));
    document.querySelectorAll('.nav-tab-btn').forEach(el => el.classList.remove('active'));

    const activeView = document.getElementById('view-' + viewName);
    if (activeView) activeView.classList.add('active');

    const tabBtn = document.getElementById('tab-' + viewName);
    if (tabBtn) tabBtn.classList.add('active');

    if (viewName === 'table') renderTableRows();
    if (viewName === 'dashboard') fetchCloudTopics(false);
    if (viewName === 'videos') loadPWVideoHub();
  }

  function openModal(id) { document.getElementById(id).classList.add('active'); }
  function closeModal(id) { document.getElementById(id).classList.remove('active'); }

  // Table Controller
  function renderTableRows() {
    const tbody = document.getElementById('editor-tbody');
    if (!tbody) return;
    tbody.innerHTML = '';

    tableQuestions.forEach((q, idx) => {
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td style="text-align:center; font-weight:700; color:var(--accent-cyan);">${idx + 1}</td>
        <td><input type="text" class="table-input" value="${escapeAttr(q.question)}" onchange="updateCell(${idx}, 'question', this.value)" placeholder="Enter question..." /></td>
        <td><input type="text" class="table-input" value="${escapeAttr(q.optionA)}" onchange="updateCell(${idx}, 'optionA', this.value)" placeholder="Option A" /></td>
        <td><input type="text" class="table-input" value="${escapeAttr(q.optionB)}" onchange="updateCell(${idx}, 'optionB', this.value)" placeholder="Option B" /></td>
        <td><input type="text" class="table-input" value="${escapeAttr(q.optionC)}" onchange="updateCell(${idx}, 'optionC', this.value)" placeholder="Option C" /></td>
        <td><input type="text" class="table-input" value="${escapeAttr(q.optionD)}" onchange="updateCell(${idx}, 'optionD', this.value)" placeholder="Option D" /></td>
        <td style="text-align:center;">
          <select class="table-select-ans" onchange="updateCell(${idx}, 'answer', this.value)">
            <option value="A" ${q.answer === 'A' ? 'selected' : ''}>A</option>
            <option value="B" ${q.answer === 'B' ? 'selected' : ''}>B</option>
            <option value="C" ${q.answer === 'C' ? 'selected' : ''}>C</option>
            <option value="D" ${q.answer === 'D' ? 'selected' : ''}>D</option>
          </select>
        </td>
        <td><input type="text" class="table-input" value="${escapeAttr(q.solution || '')}" onchange="updateCell(${idx}, 'solution', this.value)" placeholder="Explanation..." /></td>
        <td style="text-align:center;">
          <button class="btn-del-row" onclick="deleteTableRow(${idx})" title="Delete Question">🗑️</button>
        </td>
      `;
      tbody.appendChild(tr);
    });

    document.getElementById('lbl-table-count').innerText = `${tableQuestions.length} Questions`;
  }

  function updateCell(idx, field, value) {
    if (tableQuestions[idx]) tableQuestions[idx][field] = value;
  }

  function addNewEmptyRow() {
    tableQuestions.push({ question: "", optionA: "", optionB: "", optionC: "", optionD: "", answer: "A", solution: "" });
    renderTableRows();
    const wrap = document.querySelector('.quiz-editor-table-wrap');
    if (wrap) wrap.scrollTop = wrap.scrollHeight;
  }

  function deleteTableRow(idx) {
    tableQuestions.splice(idx, 1);
    renderTableRows();
  }

  function clearAllTableRows() {
    if (confirm("Clear all questions from table?")) {
      tableQuestions = [];
      renderTableRows();
      showToast("Table Cleared", "🧹");
    }
  }

  function startQuizFromTable() {
    const validQuestions = tableQuestions.filter(q => q.question && q.question.trim());
    if (!validQuestions.length) return alert("Please add at least one question to the table first!");
    startQuizWithData(validQuestions, "Laptop Practice Test");
  }

  // Save / Load Local
  function saveLocalQuizzes() {
    if (!tableQuestions.length) return alert("Table is empty!");
    const title = prompt("Enter a name for this Local Quiz:", "My Saved Quiz " + new Date().toLocaleDateString());
    if (!title) return;

    const saved = JSON.parse(localStorage.getItem('copypro_local_quizzes') || '[]');
    saved.unshift({ id: 'local_' + Date.now(), title: title, date: new Date().toLocaleString(), questions: tableQuestions });
    localStorage.setItem('copypro_local_quizzes', JSON.stringify(saved));

    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(tableQuestions, null, 2));
    const dlAnchor = document.createElement('a');
    dlAnchor.setAttribute("href", dataStr);
    dlAnchor.setAttribute("download", `${title.replace(/\s+/g, '_')}.json`);
    dlAnchor.click();

    showToast(`Saved '${title}' Locally!`, "💾");
  }

  function openLoadLocalModal() {
    const listContainer = document.getElementById('local-storage-list');
    const saved = JSON.parse(localStorage.getItem('copypro_local_quizzes') || '[]');
    if (!saved.length) {
      listContainer.innerHTML = '<p style="color:var(--text-dim); font-size:13px;">No saved quizzes found in browser storage.</p>';
    } else {
      listContainer.innerHTML = saved.map((item, idx) => `
        <div style="background:var(--bg-input); border:1px solid var(--border-color); padding:10px 12px; border-radius:6px; display:flex; justify-content:space-between; align-items:center;">
          <div>
            <div style="font-weight:700; color:#FFF; font-size:13.5px;">${escapeHtml(item.title)}</div>
            <div style="font-size:11.5px; color:var(--text-dim);">${item.questions.length} Questions • ${item.date}</div>
          </div>
          <div style="display:flex; gap:6px;">
            <button class="btn-primary" onclick="loadLocalStorageItem(${idx})">Load</button>
            <button class="btn-del-row" onclick="deleteLocalStorageItem(${idx})">🗑️</button>
          </div>
        </div>
      `).join('');
    }
    openModal('load-local-modal');
  }

  function loadLocalStorageItem(idx) {
    const saved = JSON.parse(localStorage.getItem('copypro_local_quizzes') || '[]');
    if (saved[idx]) {
      tableQuestions = saved[idx].questions;
      renderTableRows();
      closeModal('load-local-modal');
      switchView('table');
      showToast(`Loaded '${saved[idx].title}'!`, "📁");
    }
  }

  function deleteLocalStorageItem(idx) {
    const saved = JSON.parse(localStorage.getItem('copypro_local_quizzes') || '[]');
    saved.splice(idx, 1);
    localStorage.setItem('copypro_local_quizzes', JSON.stringify(saved));
    openLoadLocalModal();
  }

  async function handleLocalFileUpload(event) {
    const file = event.target.files[0];
    if (!file) return;
    const fileName = file.name.toLowerCase();

    // 🗄️ SQLITE DATABASE (.db, .sqlite, .sqlite3) SUPPORT
    if (fileName.endsWith('.db') || fileName.endsWith('.sqlite') || fileName.endsWith('.sqlite3')) {
      showToast("⏳ Reading SQLite DB file...", "🔄");
      try {
        if (typeof window.initSqlJs === 'undefined') {
          await new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.src = 'https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.8.0/sql-wasm.js';
            script.onload = resolve;
            script.onerror = reject;
            document.head.appendChild(script);
          });
        }
        const SQL = await window.initSqlJs({
          locateFile: f => `https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.8.0/${f}`
        });

        const arrayBuffer = await file.arrayBuffer();
        const uInt8Array = new Uint8Array(arrayBuffer);
        const sqliteDb = new SQL.Database(uInt8Array);

        // Fetch all non-internal tables
        const tablesRes = sqliteDb.exec("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%';");
        if (!tablesRes.length || !tablesRes[0].values.length) {
          alert("No tables found in this SQLite database.");
          return;
        }

        const tableNames = tablesRes[0].values.map(v => v[0]);
        // Pick best table (prioritize question/quiz/mcq/test)
        let chosenTable = tableNames.find(t => /question|quiz|mcq|test/i.test(t)) || tableNames[0];

        // Read table contents
        const queryRes = sqliteDb.exec(`SELECT * FROM "${chosenTable}"`);
        if (!queryRes.length || !queryRes[0].values.length) {
          alert(`Table "${chosenTable}" is empty.`);
          return;
        }

        const cols = queryRes[0].columns.map(c => c.toLowerCase());
        const rows = queryRes[0].values;

        function findColIdx(...patterns) {
          for (let p of patterns) {
            for (let i = 0; i < cols.length; i++) {
              if (cols[i] === p || cols[i].startsWith(p + '_') || cols[i].endsWith('_' + p) || cols[i].includes(p)) {
                return i;
              }
            }
          }
          return -1;
        }

        const qIdx = findColIdx('question_en', 'question', 'q', 'question_text', 'title', 'prompt');
        const qHnIdx = findColIdx('question_hn', 'question_hi', 'question_hindi');
        const optAIdx = findColIdx('option_1_en', 'option_1', 'optiona', 'option_a', 'opta', 'opt1', 'choice_a', 'choice1', 'opt_1', 'a');
        const optBIdx = findColIdx('option_2_en', 'option_2', 'optionb', 'option_b', 'optb', 'opt2', 'choice_b', 'choice2', 'opt_2', 'b');
        const optCIdx = findColIdx('option_3_en', 'option_3', 'optionc', 'option_c', 'optc', 'opt3', 'choice_c', 'choice3', 'opt_3', 'c');
        const optDIdx = findColIdx('option_4_en', 'option_4', 'optiond', 'option_d', 'optd', 'opt4', 'choice_d', 'choice4', 'opt_4', 'd');
        const ansIdx = findColIdx('correct_option', 'answer', 'correct_ans', 'ans', 'correct', 'answer_key', 'key');
        const solIdx = findColIdx('solution_en', 'solution', 'explanation', 'exp', 'sol', 'solution_hn');

        function cleanHtml(val) {
          if (val === null || val === undefined) return "";
          let s = String(val).replace(/<br\s*[\/]?>/gi, "\n").replace(/<\/p>/gi, "\n").replace(/<[^>]+>/g, "");
          const txt = document.createElement("textarea");
          txt.innerHTML = s;
          return txt.value.trim();
        }

        const parsedFromDb = [];
        for (let r of rows) {
          let qEn = qIdx >= 0 ? cleanHtml(r[qIdx]) : "";
          let qHn = qHnIdx >= 0 ? cleanHtml(r[qHnIdx]) : "";
          let qText = "";
          if (qEn && qHn && qEn !== qHn) {
            qText = qEn + "\n\n[Hindi]: " + qHn;
          } else {
            qText = qEn || qHn || "";
          }

          let optA = optAIdx >= 0 ? cleanHtml(r[optAIdx]) : "";
          let optB = optBIdx >= 0 ? cleanHtml(r[optBIdx]) : "";
          let optC = optCIdx >= 0 ? cleanHtml(r[optCIdx]) : "";
          let optD = optDIdx >= 0 ? cleanHtml(r[optDIdx]) : "";

          let rawAns = ansIdx >= 0 && r[ansIdx] !== null ? String(r[ansIdx]).trim() : "";
          let ans = "A";
          if (rawAns === "1" || rawAns === "1.0") ans = "A";
          else if (rawAns === "2" || rawAns === "2.0") ans = "B";
          else if (rawAns === "3" || rawAns === "3.0") ans = "C";
          else if (rawAns === "4" || rawAns === "4.0") ans = "D";
          else if (['A', 'B', 'C', 'D'].includes(rawAns.toUpperCase())) ans = rawAns.toUpperCase();
          else {
            if (optA && rawAns === optA) ans = "A";
            else if (optB && rawAns === optB) ans = "B";
            else if (optC && rawAns === optC) ans = "C";
            else if (optD && rawAns === optD) ans = "D";
            else ans = rawAns || "A";
          }

          let sol = solIdx >= 0 ? cleanHtml(r[solIdx]) : "";

          if (qText || optA || optB) {
            parsedFromDb.push({
              question: qText,
              optionA: optA,
              optionB: optB,
              optionC: optC,
              optionD: optD,
              answer: ans,
              solution: sol
            });
          }
        }

        if (parsedFromDb.length) {
          tableQuestions = parsedFromDb;
          renderTableRows();
          closeModal('load-local-modal');
          switchView('table');
          showToast(`Loaded ${parsedFromDb.length} questions from ${file.name}!`, "✅");
        } else {
          alert("Could not extract any questions from the SQLite DB.");
        }
      } catch (err) {
        console.error(err);
        alert("Failed to load SQLite DB: " + err.message);
      }
      return;
    }

    // 📊 EXCEL (.xlsx, .xls) SUPPORT
    if (fileName.endsWith('.xlsx') || fileName.endsWith('.xls')) {
      showToast("⏳ Reading Excel file...", "🔄");
      try {
        if (typeof window.XLSX === 'undefined') {
          await new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.src = 'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';
            script.onload = resolve;
            script.onerror = reject;
            document.head.appendChild(script);
          });
        }
        const data = await file.arrayBuffer();
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(firstSheet, { header: 1 });

        const parsedExcel = [];
        for (let row of jsonData) {
          if (!row || !row.length) continue;
          const firstVal = String(row[0] || '').trim().toLowerCase();
          if (['question', 'q', 'questions', 'mcq'].includes(firstVal)) continue;
          if (row.some(v => String(v || '').trim())) {
            parsedExcel.push({
              question: String(row[0] || '').trim(),
              optionA: String(row[1] || '').trim(),
              optionB: String(row[2] || '').trim(),
              optionC: String(row[3] || '').trim(),
              optionD: String(row[4] || '').trim(),
              answer: String(row[5] || 'A').trim().toUpperCase(),
              solution: String(row[6] || '').trim()
            });
          }
        }
        if (parsedExcel.length) {
          tableQuestions = parsedExcel;
          renderTableRows();
          closeModal('load-local-modal');
          switchView('table');
          showToast(`Loaded ${parsedExcel.length} questions from Excel!`, "✅");
          return;
        }
      } catch (err) {
        console.error(err);
      }
    }

    // 📄 JSON / TEXT / CSV / TSV SUPPORT
    const reader = new FileReader();
    reader.onload = function(e) {
      const content = e.target.result;
      try {
        const parsedJson = JSON.parse(content);
        if (Array.isArray(parsedJson)) {
          tableQuestions = parsedJson;
          renderTableRows();
          closeModal('load-local-modal');
          switchView('table');
          showToast(`Loaded ${parsedJson.length} questions from JSON!`, "✅");
          return;
        }
      } catch(err) {}

      const parsedText = parseUniversalMCQ(content, 'auto', true);
      if (parsedText.length) {
        tableQuestions = parsedText;
        renderTableRows();
        closeModal('load-local-modal');
        switchView('table');
        showToast(`Loaded ${parsedText.length} questions from file!`, "✅");
      } else {
        alert("Could not parse questions from file.");
      }
    };
    reader.readAsText(file);
  }

  // Cloud Sync (Admin Protected)
  function openCloudSyncModal() {
    if (!db) return alert("Firebase is not initialized!");
    if (!tableQuestions.length) return alert("Table is empty! Add questions first.");
    openModal('cloud-sync-modal');
  }

  async function performCloudSync() {
    if (!isAdminLoggedIn()) return alert("Unauthorized! Please login as Admin.");
    const topic = document.getElementById('sync-topic').value.trim();
    const subject = document.getElementById('sync-subject').value.trim();
    const testCode = document.getElementById('sync-test-code').value.trim().toUpperCase();
    const statusMsg = document.getElementById('sync-status-msg');

    if (!topic || !subject || !testCode) return alert("Please fill Topic, Subject and Test Code!");
    statusMsg.innerText = "⏳ Uploading batch to Firebase...";

    try {
      const batch = db.batch();
      tableQuestions.forEach(q => {
        const docRef = db.collection("quizzes").doc();
        batch.set(docRef, {
          topic: topic,
          subject: subject,
          test_code: testCode,
          question: q.question || "",
          optionA: q.optionA || "",
          optionB: q.optionB || "",
          optionC: q.optionC || "",
          optionD: q.optionD || "",
          answer: q.answer || "A",
          solution: q.solution || "",
          timestamp: firebase.firestore.FieldValue.serverTimestamp()
        });
      });

      await batch.commit();
      statusMsg.innerText = "✅ Successfully synced to Firebase!";
      showToast(`Synced '${topic}' to Cloud Database!`, "🔥");
      closeModal('cloud-sync-modal');
      fetchCloudTopics(true);
    } catch(err) {
      statusMsg.innerText = "❌ Sync failed: " + err.message;
      alert("Cloud Sync failed: " + err.message);
    }
  }

  // Cloud History (Admin Protected)
  function openCloudHistoryModal() {
    openModal('cloud-history-modal');
    loadCloudHistoryList(false);
  }

  async function loadCloudHistoryList(forceFresh) {
    const tbody = document.getElementById('cloud-history-tbody');

    if (allCloudTopics.length && !forceFresh) {
      renderCloudHistoryTable(allCloudTopics);
      return;
    }

    tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; color:var(--text-dim); padding:20px;">⏳ Loading tests from Firebase Firestore...</td></tr>';
    if (!db) {
      tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; color:var(--accent-red); padding:20px;">Firebase not connected.</td></tr>';
      return;
    }

    await fetchCloudTopics(forceFresh);
    renderCloudHistoryTable(allCloudTopics);
  }

  function renderCloudHistoryTable(topics) {
    const tbody = document.getElementById('cloud-history-tbody');
    if (!tbody) return;
    if (!topics.length) {
      tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; color:var(--text-dim); padding:20px;">No tests found in cloud database. Use "Cloud Sync" to upload tests!</td></tr>';
      return;
    }

    tbody.innerHTML = topics.map((t, idx) => `
      <tr>
        <td style="font-weight:700; color:#FFF;">${escapeHtml(t.topic)}</td>
        <td><span class="quiz-subject-badge">${escapeHtml(t.subject)}</span></td>
        <td style="font-family:var(--font-heading); font-weight:700; color:var(--accent-cyan);">${escapeHtml(t.test_code)}</td>
        <td style="color:var(--text-muted);">${t.count} Questions</td>
        <td style="text-align:center; display:flex; gap:6px; justify-content:center; flex-wrap:wrap;">
          <button class="btn-primary" onclick="loadCloudTopicToTable(${idx})" title="Load into Table Editor">📥 Edit</button>
          <button class="btn-success" onclick="startCloudTopicQuiz(${idx})" title="Play CBT Quiz">🎮 Play</button>
          <button class="btn-del-row" onclick="deleteCloudTopic(${idx})" title="Delete from Cloud">🗑️</button>
        </td>
      </tr>
    `).join('');
  }

  function loadCloudTopicToTable(idx) {
    const item = allCloudTopics[idx];
    if (item && item.docs && item.docs.length) {
      tableQuestions = item.docs.map(d => ({
        question: d.question || "",
        optionA: d.optionA || "",
        optionB: d.optionB || "",
        optionC: d.optionC || "",
        optionD: d.optionD || "",
        answer: d.answer || "A",
        solution: d.solution || ""
      }));
      renderTableRows();
      closeModal('cloud-history-modal');
      switchView('table');
      showToast(`Loaded ${tableQuestions.length} questions into table!`, "📥");
    }
  }

  function startCloudTopicQuiz(idx) {
    const item = allCloudTopics[idx];
    if (item && item.docs && item.docs.length) {
      closeModal('cloud-history-modal');
      startQuizWithData(item.docs, item.topic);
    }
  }

  async function deleteCloudTopic(idx) {
    const item = allCloudTopics[idx];
    if (!item) return;

    requireAdminAuth(async () => {
      if (confirm(`Delete all ${item.count} questions of '${item.topic}' from Cloud Database?`)) {
        try {
          showToast(`Deleting '${item.topic}'...`, "⏳");
          const batch = db.batch();
          if (item.docIds && item.docIds.length) {
            item.docIds.forEach(id => batch.delete(db.collection("quizzes").doc(id)));
          } else {
            const snap = await db.collection("quizzes").where("topic", "==", item.topic).get();
            snap.forEach(doc => batch.delete(doc.ref));
          }
          await batch.commit();
          showToast(`Deleted '${item.topic}'!`, "🗑️");
          fetchCloudTopics(true);
        } catch(err) {
          alert("Failed to delete: " + err.message);
        }
      }
    });
  }

