  function loadLocalCachedTopics() {
    try {
      const cached = localStorage.getItem('copypro_cloud_all_v4');
      if (cached) {
        allCloudTopics = JSON.parse(cached);
        if (allCloudTopics && allCloudTopics.length) {
          updateDatabaseStats();
          renderSubjectTabs(allCloudTopics);
          renderCloudDashboard(allCloudTopics);
          return true;
        }
      }
    } catch(e) {}

    if (typeof DEFAULT_FALLBACK_TOPICS !== 'undefined' && DEFAULT_FALLBACK_TOPICS.length) {
      allCloudTopics = JSON.parse(JSON.stringify(DEFAULT_FALLBACK_TOPICS));
      try {
        localStorage.setItem('copypro_cloud_all_v4', JSON.stringify(allCloudTopics));
      } catch(e) {}
      updateDatabaseStats();
      renderSubjectTabs(allCloudTopics);
      renderCloudDashboard(allCloudTopics);
      return true;
    }

    return false;
  }

  function updateDatabaseStats() {
    let totalQs = 0;
    allCloudTopics.forEach(t => totalQs += (t.count || (t.docs ? t.docs.length : 0)));
    const totalLbl = document.getElementById('lbl-total-db-count');
    if (totalLbl) {
      totalLbl.innerText = `${allCloudTopics.length} Tests (${totalQs} Questions)`;
    }
  }

  function renderSkeletonShimmer() {
    const grid = document.getElementById('topics-grid');
    if (!grid) return;
    grid.innerHTML = Array(8).fill(0).map(() => `<div class="skeleton-card"></div>`).join('');
  }

  async function fetchCloudTopics(forceFresh) {
    if (!db || isFetchingCloud) return;
    isFetchingCloud = true;

    const hasCache = loadLocalCachedTopics();
    if (!hasCache) renderSkeletonShimmer();

    try {
      const snapshot = await db.collection("quizzes").get();

      const grouped = {};
      snapshot.forEach(doc => {
        const d = doc.data();
        const topic = (d.topic || d.title || d.topic_name || "Untitled Topic").trim();
        let subject = (d.subject || d.category || d.subject_name || "General").trim();

        if (subject.toLowerCase() === 'current affairs') subject = 'Current Affairs';
        else if (subject.toLowerCase() === 'technology') subject = 'Technology';
        else if (subject.toLowerCase() === 'mathematics' || subject.toLowerCase() === 'maths') subject = 'Mathematics';
        else if (subject.toLowerCase() === 'english') subject = 'English';

        const testCode = (d.test_code || d.testCode || d.code || "T01").trim().toUpperCase();

        const key = topic + "|||" + subject;
        if (!grouped[key]) {
          grouped[key] = {
            topic: topic,
            subject: subject,
            test_code: testCode,
            count: 0,
            docs: [],
            docIds: []
          };
        }

        const qObj = {
          question: d.question || d.q || d.text || "",
          optionA: d.optionA || d.option_a || d.optA || d.a || "",
          optionB: d.optionB || d.option_b || d.optB || d.b || "",
          optionC: d.optionC || d.option_c || d.optC || d.c || "",
          optionD: d.optionD || d.option_d || d.optD || d.d || "",
          answer: (d.answer || d.ans || d.correct || "A").toString().trim().toUpperCase(),
          solution: d.solution || d.explanation || d.details || d.sol || ""
        };

        grouped[key].count++;
        grouped[key].docs.push(qObj);
        grouped[key].docIds.push(doc.id);
      });

      allCloudTopics = Object.values(grouped).sort((a, b) => {
        if (a.subject !== b.subject) return a.subject.localeCompare(b.subject);
        return a.topic.localeCompare(b.topic, undefined, { numeric: true, sensitivity: 'base' });
      });

      try {
        localStorage.setItem('copypro_cloud_all_v4', JSON.stringify(allCloudTopics));
      } catch(e) {}

      updateDatabaseStats();
      renderSubjectTabs(allCloudTopics);
    } catch(err) {
      console.warn("Cloud load notice:", err);
      loadLocalCachedTopics();
      if (err.message && (err.message.includes('Quota') || err.message.includes('RESOURCE_EXHAUSTED') || err.code === 'resource-exhausted')) {
        showToast("Loaded Offline Test Library 💾", "📚");
      }
    } finally {
      isFetchingCloud = false;
    }
  }

  function renderSubjectTabs(topics) {
    const container = document.getElementById('subject-tabs-container');
    if (!container) return;

    const subjectCounts = {};
    topics.forEach(t => {
      const s = (t.subject || "General").trim();
      subjectCounts[s] = (subjectCounts[s] || 0) + 1;
    });

    const subjects = Object.keys(subjectCounts).sort();
    let totalCount = topics.length;

    let html = `
      <button class="subject-tab-pill ${currentSubjectFilter === 'ALL' ? 'active' : ''}" onclick="filterBySubject('ALL')">
        <span>📚 All Subjects</span>
        <span class="subject-tab-count">${totalCount}</span>
      </button>
    `;

    subjects.forEach(subj => {
      const count = subjectCounts[subj];
      const isActive = (currentSubjectFilter.toLowerCase() === subj.toLowerCase());
      html += `
        <button class="subject-tab-pill ${isActive ? 'active' : ''}" onclick="filterBySubject('${escapeAttr(subj)}')">
          <span>🏷️ ${escapeHtml(subj)}</span>
          <span class="subject-tab-count">${count}</span>
        </button>
      `;
    });

    container.innerHTML = html;
  }

  function filterBySubject(subj) {
    currentSubjectFilter = subj;
    renderSubjectTabs(allCloudTopics);
    renderCloudDashboard(allCloudTopics);
  }

  function onSearchCloudTests(query) {
    currentSearchQuery = query.toLowerCase().trim();
    renderCloudDashboard(allCloudTopics);
  }

  function renderCloudDashboard(topics) {
    const grid = document.getElementById('topics-grid');
    if (!grid) return;

    let filtered = topics;
    if (currentSubjectFilter !== "ALL") {
      filtered = filtered.filter(t => (t.subject || "General").toLowerCase() === currentSubjectFilter.toLowerCase());
    }

    if (currentSearchQuery) {
      filtered = filtered.filter(t => 
        (t.topic && t.topic.toLowerCase().includes(currentSearchQuery)) ||
        (t.subject && t.subject.toLowerCase().includes(currentSearchQuery)) ||
        (t.test_code && t.test_code.toLowerCase().includes(currentSearchQuery))
      );
    }

    if (!filtered.length) {
      grid.innerHTML = '<p style="color:var(--text-muted); text-align:center; grid-column:1/-1; padding:30px;">No matching tests found in this category.</p>';
      return;
    }

    const isAdmin = isAdminLoggedIn();

    grid.innerHTML = filtered.map((t) => {
      const globalIdx = allCloudTopics.indexOf(t);
      return `
        <div class="quiz-card">
          <div>
            <div style="display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:10px;">
              <span class="quiz-subject-badge">${escapeHtml(t.subject)}</span>
              <span style="font-size:12px; font-weight:700; color:var(--text-dim);">${escapeHtml(t.test_code)}</span>
            </div>
            <div style="font-family:var(--font-heading); font-size:16px; font-weight:700; margin-bottom:8px; color:#FFF;">${escapeHtml(t.topic)}</div>
            <div style="display:flex; gap:12px; color:var(--text-muted); font-size:12px; margin-bottom:14px;">
              <div>📝 <span>${t.count} Qs</span></div>
              <div>⏱️ <span>${Math.max(5, Math.round(t.count * 1.5))} Mins</span></div>
            </div>
          </div>
          <div style="display:flex; justify-content:space-between; align-items:center; border-top:1px solid rgba(255,255,255,0.05); padding-top:12px; gap:8px;">
            ${isAdmin ? `
              <button class="btn-ctrl" onclick="loadCloudTopicToTable(${globalIdx})" style="flex:1;">📥 Edit</button>
              <button class="btn-success" onclick="startCloudTopicQuiz(${globalIdx})" style="flex:1;">Start 🚀</button>
            ` : `
              <button class="btn-success" onclick="startCloudTopicQuiz(${globalIdx})" style="width:100%; padding:9px 14px; font-size:13px;">Start Test 🚀</button>
            `}
          </div>
        </div>
      `;
    }).join('');
  }

  function launchByTestCode() {
    const code = document.getElementById('input-test-code').value.trim().toUpperCase();
    if (!code) return alert("Please enter a Test Code or Topic name!");
    const match = allCloudTopics.find(t => t.test_code.toUpperCase() === code || t.topic.toUpperCase().includes(code));
    if (match && match.docs && match.docs.length) {
      startQuizWithData(match.docs, match.topic);
    } else {
      alert("Test Code / Topic '" + code + "' not found in cloud database.");
    }
  }

  function openBulkModal() { openModal('bulk-modal'); }
  async function pasteFromClipboard() {
    try {
      const text = await navigator.clipboard.readText();
      document.getElementById('modal-bulk-input').value = text;
    } catch(err) {
      alert("Press Ctrl + V inside the box to paste!");
    }
  }

  function processBulkImport() {
    const raw = document.getElementById('modal-bulk-input').value.trim();
    if (!raw) return alert("Please paste data first!");

    const userDelim = document.getElementById('bulk-delimiter').value;
    const skipHeader = document.getElementById('bulk-skip-header').checked;

    const parsed = parseUniversalMCQ(raw, userDelim, skipHeader);
    if (!parsed.length) {
      alert("Could not parse data. Ensure data has columns: Question, A, B, C, D, Ans, Solution");
      return;
    }

    tableQuestions = parsed;
    renderTableRows();
    closeModal('bulk-modal');
    switchView('table');
    showToast(`Imported ${parsed.length} questions!`, "✅");
  }

  function parseUniversalMCQ(rawText, userDelim, skipHeader) {
    const lines = rawText.split('\n').map(l => l.trim()).filter(l => l);
    if (!lines.length) return [];

    let delimiter = userDelim;
    if (delimiter === 'auto') {
      const sample = lines[0];
      if (sample.includes('\t')) delimiter = '\t';
      else if (sample.includes('|')) delimiter = '|';
      else if (sample.includes(';')) delimiter = ';';
      else if (sample.includes(',') && sample.split(',').length >= 4) delimiter = ',';
    }

    const results = [];
    if (delimiter && delimiter !== 'auto') {
      let startIdx = 0;
      const firstParts = lines[0].split(delimiter).map(p => p.trim().toLowerCase());
      if (skipHeader || firstParts[0].includes('question') || firstParts[0].includes('q') || firstParts[1] === 'a') {
        startIdx = 1;
      }

      for (let i = startIdx; i < lines.length; i++) {
        const parts = lines[i].split(delimiter).map(p => p.trim());
        if (parts.length >= 2) {
          const qText = parts[0];
          const optA = parts[1] || "";
          const optB = parts[2] || "";
          const optC = parts[3] || "";
          const optD = parts[4] || "";
          let ansRaw = (parts[5] || "A").toUpperCase();
          let ans = "A";
          if (ansRaw.includes('B') || ansRaw === '2') ans = "B";
          else if (ansRaw.includes('C') || ansRaw === '3') ans = "C";
          else if (ansRaw.includes('D') || ansRaw === '4') ans = "D";
          else if (ansRaw.includes('A') || ansRaw === '1') ans = "A";

          const sol = parts[6] || "";
          results.push({ question: qText, optionA: optA, optionB: optB, optionC: optC, optionD: optD, answer: ans, solution: sol });
        }
      }
      if (results.length > 0) return results;
    }
    return [];
  }

  // ==========================================================================
  // CBT QUIZ PLAYER
  // ==========================================================================
  function startQuizWithData(questionsList, topicTitle) {
    currentQuizData = questionsList;
    currentIdx = 0;
    userAnswers = {};
    markedForReview.clear();
    timerSeconds = Math.max(300, questionsList.length * 90);

    document.getElementById('tab-player').style.display = 'inline-flex';
    switchView('player');

    buildPalette();
    loadQuestion(0);
    startTimer();
    initEarbudsEngine();
  }

  function buildPalette() {
    const grid = document.getElementById('palette-grid');
    grid.innerHTML = currentQuizData.map((_, i) => `
      <button class="palette-btn" id="pal-btn-${i}" onclick="loadQuestion(${i})">${i + 1}</button>
    `).join('');
    updatePalette();
  }

  function updatePalette() {
    currentQuizData.forEach((_, i) => {
      const btn = document.getElementById(`pal-btn-${i}`);
      if (!btn) return;
      btn.className = "palette-btn";
      if (i === currentIdx) btn.classList.add("current");
      if (i in userAnswers) btn.classList.add("answered");
      if (markedForReview.has(i)) btn.classList.add("marked");
    });
    const solvedCount = Object.keys(userAnswers).length;
    document.getElementById('lbl-palette-score').innerText = `${solvedCount} / ${currentQuizData.length} Solved`;
  }

  function loadQuestion(idx) {
    if (idx < 0 || idx >= currentQuizData.length) return;
    currentIdx = idx;
    const q = currentQuizData[idx];

    document.getElementById('lbl-q-counter').innerText = `Q ${idx + 1} / ${currentQuizData.length}`;
    document.getElementById('lbl-q-text').innerText = formatDualText(q.question);

    const letters = ['A', 'B', 'C', 'D'];
    letters.forEach((l, i) => {
      const btn = document.getElementById(`opt-btn-${i}`);
      const textEl = document.getElementById(`opt-text-${i}`);
      btn.className = "opt-btn";
      btn.disabled = false;
      textEl.innerText = formatDualText(q['option' + l] || '');
    });

    const solBox = document.getElementById('sol-box');
    if (idx in userAnswers) {
      const selected = userAnswers[idx];
      const correctIdx = getCorrectIdx(q);

      letters.forEach((_, i) => {
        const btn = document.getElementById(`opt-btn-${i}`);
        btn.disabled = true;
        if (i === correctIdx) btn.classList.add('selected-correct');
        if (selected !== correctIdx && i === selected) btn.classList.add('selected-wrong');
      });

      document.getElementById('lbl-sol-text').innerText = q.solution || "No explanation provided.";
      solBox.style.display = 'block';
    } else {
      solBox.style.display = 'none';
      if (audioReadEnabled) speakCurrentQuestion();
    }

    updatePalette();
    setupMediaSession();
  }

  function getCorrectIdx(q) {
    const raw = (q.answer || 'A').toString().trim().toUpperCase();
    const letters = ['A', 'B', 'C', 'D'];
    for (let i = 0; i < 4; i++) {
      if (raw.includes(letters[i]) || raw === (i + 1).toString()) return i;
    }
    return 0;
  }

  function selectOption(selectedIdx) {
    if (currentIdx in userAnswers) return;
    const q = currentQuizData[currentIdx];
    const correctIdx = getCorrectIdx(q);

    userAnswers[currentIdx] = selectedIdx;
    const isCorrect = (selectedIdx === correctIdx);
    playSound(isCorrect ? 'correct' : 'wrong');

    const letters = ['A', 'B', 'C', 'D'];
    letters.forEach((_, i) => {
      const btn = document.getElementById(`opt-btn-${i}`);
      btn.disabled = true;
      if (i === correctIdx) btn.classList.add('selected-correct');
      if (!isCorrect && i === selectedIdx) btn.classList.add('selected-wrong');
    });

    document.getElementById('lbl-sol-text').innerText = q.solution || "No explanation provided.";
    document.getElementById('sol-box').style.display = 'block';

    updatePalette();
  }

  function nextQuestion() {
    if (currentIdx < currentQuizData.length - 1) loadQuestion(currentIdx + 1);
    else submitQuizConfirm();
  }

  function prevQuestion() {
    if (currentIdx > 0) loadQuestion(currentIdx - 1);
  }

  function toggleMarkReview() {
    if (markedForReview.has(currentIdx)) markedForReview.delete(currentIdx);
    else markedForReview.add(currentIdx);
    updatePalette();
  }

  function clearResponse() {
    delete userAnswers[currentIdx];
    loadQuestion(currentIdx);
  }

  function toggleSolutionView() {
    const box = document.getElementById('sol-box');
    box.style.display = box.style.display === 'block' ? 'none' : 'block';
  }

  function startTimer() {
    if (timerInterval) clearInterval(timerInterval);
    timerInterval = setInterval(() => {
      timerSeconds--;
      if (timerSeconds <= 0) {
        clearInterval(timerInterval);
        submitQuizResults();
        return;
      }
      const m = Math.floor(timerSeconds / 60).toString().padStart(2, '0');
      const s = (timerSeconds % 60).toString().padStart(2, '0');
      document.getElementById('lbl-timer').innerText = `⏱️ ${m}:${s}`;
    }, 1000);
  }

  function submitQuizConfirm() {
    const solved = Object.keys(userAnswers).length;
    const total = currentQuizData.length;
    if (confirm(`Submit Test? You have answered ${solved} of ${total} questions.`)) {
      submitQuizResults();
    }
  }

  function submitQuizResults() {
    if (timerInterval) clearInterval(timerInterval);
    if (recognition) { try { recognition.stop(); } catch(e){} }
    stopStudioVoice();
    if (earbudAudioEl) try { earbudAudioEl.pause(); } catch(e){}

    let correctCount = 0;
    currentQuizData.forEach((q, idx) => {
      if (userAnswers[idx] === getCorrectIdx(q)) correctCount++;
    });

    const total = currentQuizData.length;
    const percent = Math.round((correctCount / total) * 100);

    document.getElementById('res-score').innerText = `${correctCount} / ${total}`;
    document.getElementById('res-percent').innerText = `${percent}% Accuracy`;
    document.getElementById('res-correct').innerText = correctCount;
    document.getElementById('res-wrong').innerText = total - correctCount;

    const m = Math.floor((900 - timerSeconds) / 60);
    const s = (900 - timerSeconds) % 60;
    document.getElementById('res-time').innerText = `${m}m ${s}s`;
    switchView('results');
  }

  function restartQuiz() {
    startQuizWithData(currentQuizData, "Retake Practice Test");
  }

  if ('speechSynthesis' in window) {
    window.speechSynthesis.onvoiceschanged = () => { loadBrowserVoices(); };
  }

  window.addEventListener('DOMContentLoaded', () => {
    renderTableRows();
    loadLocalCachedTopics();
    fetchCloudTopics(false);
    updateAdminUIState(isAdminLoggedIn());
    updateAudioInputDevices();
  });

