1-b948-af754bf48728","69a45cd6579f01e3ddeaf488"],["Population 01 ","00:55:20","68c1bec1-c65b-47cb-9603-7cfb92c7a99a","69a45c706c71571bd8b07651"]]],["National Income",[["National Income 03 ","00:58:16","ef6692a1-7e47-481b-937d-8cc513c566fa","699b170e598b634e7ea2a65b"],["National Income 02 ","01:00:16","85ea2aae-6cbd-4467-b4a6-d3ae4fa479d5","699d6c070b5190ffd95594eb"],["National Income 01 ","00:55:46","20e8a661-9741-4cf0-9a97-baf8e93ba4a9","699d6bdd93550f0a8b98dec4"]]],["Basic Concept of Economics & Microeconomic",[["Basic Concept of Economics And Microeconomic 03 ","00:59:28","2ad2488d-618a-4704-9609-b0f18174ef93","699b15127ff15ca0dd42d226"],["Basic Concept of Economics And Microeconomic 02","01:00:40","3af68f1f-45b9-41f7-8f82-99889bdd8e1c","699b2743659d2924e49d68c0"],["Basic Concept of Economics And Microeconomic 01 ","00:56:20","3eb6758c-d28f-4e9e-bd17-67fdbd847a9b","69987657d400f93e54ab2e19"]]],["Finance Commission",[["Finance Commission 01 ","00:46:24","8e76a302-9418-48ea-b5ab-811cfda16569","6992b3328ca53363e854eb68"]]],["CAG",[["CAG 01 ","00:41:32","44f537d4-91e0-4d94-85a6-a0f52a3d29bf","6992af16aaeb0fd393b6f360"]]],["Banking",[["Banking 03 || Extra Class","00:55:44","cc5c57bb-6e36-4c99-b91e-cc897edf7a8f","6991e1c5f6459274cfe91c51"],["Banking 02 ","00:56:08","0c4a8c53-caf2-4f29-a151-f69f6cec0f8b","698f1439bec45a61ad4ed003"],["Banking 01 ","00:59:08","eeee07d2-a1ab-44bf-8384-4b001d8f0522","69875059ab08b4b2cbf93c49"]]],["Money",[["Money 02 ","00:59:28","c7871146-12b2-4f85-9b3d-a185e1551a6d","6987500678fabfab8b10e25b"],["Money 01 : rescheduled @11:10 AM ","00:46:56","8548120b-e249-4027-a84b-a9348117534b","69874fe0842b3ce3f4a073b6"]]],["Introduction",[["Introduction 02 ","00:54:36","77c9bda8-5b54-48e2-b3b4-07854268419a","69874faaef688fd20c6f613a"],["Introduction 01","00:47:04","cfb298a3-beda-4c37-a4b6-62203891ca05","69874f8f7b27597a9775c311"]]]]]];

  // ==================== COMPACT ULTRA-LIGHT SAFAR 4.0 BATCH ENGINE ====================
  const PW_BATCH_ID = "68b0209b7de6b2a2ce2443b1";

  // Inflate compact tree
  let PW_BATCH_TREE = [];
  try {
    if (typeof PW_RAW_TREE !== 'undefined' && Array.isArray(PW_RAW_TREE)) {
      PW_BATCH_TREE = PW_RAW_TREE.map(function(subjArr) {
        return {
          subjectName: subjArr[0],
          subjectId: subjArr[1],
          chapters: (subjArr[2] || []).map(function(chapArr) {
            return {
              chapterName: chapArr[0],
              lectures: (chapArr[1] || []).map(function(lecArr) {
                var streamRef = String(lecArr[2] || '');
                var isUrl = streamRef.indexOf('http') === 0;
                var stream = isUrl ? streamRef : ('https://d1d34p8vz63oiq.cloudfront.net/' + streamRef + '/master.mpd');
                return {
                  id: lecArr[3] || streamRef,
                  title: lecArr[0],
                  duration: lecArr[1] || '00:50:00',
                  streamUrl: stream,
                  chapter: chapArr[0],
                  subject: subjArr[0],
                  pwUrl: 'https://www.pw.live/watch/?batchSlug=' + PW_BATCH_ID + '&batchSubjectId=' + subjArr[1] + '&subjectSlug=' + subjArr[1] + '&topicSlug=all&scheduleId=' + (lecArr[3] || lecArr[2]) + '&type=penpencilvdo&isPPJEnabled=true&parentId=' + PW_BATCH_ID + '&vType=BATCHES&childId=' + (lecArr[3] || lecArr[2]),
                  thumbnail: 'https://static.pw.live/5eb393ee95fab7468a79d189/image/4a25378f-68be-4ab7-a017-cc518fab3e2d.png',
                  faculty: 'PW • ' + subjArr[0] + ' Faculty',
                  type: (stream.indexOf('.mpd') !== -1) ? 'DASH' : 'HLS'
                };
              })
            };
          })
        };
      });
    }
  } catch(e) {
    console.error('Error inflating PW_BATCH_TREE:', e);
  }

  var curSubjectIdx = 0;
  var curActiveLecture = null;
  var pwDashPlayer = null;
  var currentPWSpeed = 1.0;

  function loadPWVideoHub() {
    renderPWSubjectTabs();
    if (PW_BATCH_TREE.length > 0) {
      selectPWSubject(0);
    }
  }

  function renderPWSubjectTabs() {
    var bar = document.getElementById('pw-subject-tabs-bar');
    if (!bar) return;
    bar.innerHTML = '';

    PW_BATCH_TREE.forEach(function(s, idx) {
      var btn = document.createElement('button');
      btn.className = 'pw-subj-tab' + (idx === curSubjectIdx ? ' active' : '');

      var icon = '📚';
      var sName = s.subjectName.toUpperCase();
      if (sName.indexOf('MATH') !== -1) icon = '📐';
      else if (sName.indexOf('REASON') !== -1) icon = '🧠';
      else if (sName.indexOf('ENG') !== -1) icon = '📖';
      else if (sName.indexOf('SCI') !== -1) icon = '🔬';
      else if (sName.indexOf('HIST') !== -1) icon = '🏛️';
      else if (sName.indexOf('POLIT') !== -1) icon = '📜';
      else if (sName.indexOf('GEO') !== -1) icon = '🌍';
      else if (sName.indexOf('ECON') !== -1) icon = '📊';
      else if (sName.indexOf('COMP') !== -1) icon = '💻';

      btn.innerHTML = '<span>' + icon + '</span><span>' + s.subjectName + '</span>';
      btn.onclick = function() { selectPWSubject(idx); };
      bar.appendChild(btn);
    });
  }

  function selectPWSubject(idx) {
    curSubjectIdx = idx;
    var allTabs = document.querySelectorAll('.pw-subj-tab');
    allTabs.forEach(function(b, i) {
      if (i === idx) b.classList.add('active');
      else b.classList.remove('active');
    });

    var subj = PW_BATCH_TREE[idx];
    if (!subj) return;

    var titleEl = document.getElementById('pw-cur-subject-name');
    if (titleEl) titleEl.textContent = subj.subjectName;

    var countEl = document.getElementById('pw-total-chapters-count');
    if (countEl) countEl.textContent = subj.chapters.length + ' Chapters Total';

    renderPWChaptersAccordion(subj);

    if (subj.chapters.length > 0 && subj.chapters[0].lectures.length > 0) {
      renderPWPlaylist(subj.chapters[0].lectures, subj.chapters[0].chapterName);
      if (!curActiveLecture) {
        playPWLecture(subj.chapters[0].lectures[0]);
      }
    }
  }

  function renderPWChaptersAccordion(subj) {
    var container = document.getElementById('pw-chapters-accordion');
    if (!container) return;
    container.innerHTML = '';

    subj.chapters.forEach(function(chap, cIdx) {
      var card = document.createElement('div');
      card.className = 'pw-chapter-card' + (cIdx === 0 ? ' open' : '');

      var header = document.createElement('div');
      header.className = 'pw-chapter-header';
      header.innerHTML = '<div class="pw-chapter-title-box"><span class="pw-chapter-icon">📂</span><span class="pw-chapter-title">' + chap.chapterName + '</span></div><div class="pw-chapter-meta"><span class="pw-chapter-badge">' + chap.lectures.length + ' Lectures</span><span class="pw-chevron">▼</span></div>';
      header.onclick = function() {
        card.classList.toggle('open');
        renderPWPlaylist(chap.lectures, chap.chapterName);
      };

      var body = document.createElement('div');
      body.className = 'pw-chapter-body';
      var grid = document.createElement('div');
      grid.className = 'pw-lecture-grid';

      chap.lectures.forEach(function(lec) {
        var item = document.createElement('div');
        item.className = 'pw-lecture-item' + (curActiveLecture && curActiveLecture.id === lec.id ? ' active' : '');
        item.innerHTML = '<div class="pw-lec-title">▶ ' + lec.title + '</div><div class="pw-lec-footer"><span>⏱️ ' + lec.duration + '</span><span style="color:#A5B4FC; font-weight:600;">Play &gt;</span></div>';
        item.onclick = function(e) {
          e.stopPropagation();
          playPWLecture(lec);
        };
        grid.appendChild(item);
      });

      body.appendChild(grid);
      card.appendChild(header);
      card.appendChild(body);
      container.appendChild(card);
    });
  }

  function renderPWPlaylist(lectures, chapterName) {
    var container = document.getElementById('yt-playlist-cards');
    if (!container) return;
    container.innerHTML = '';

    var titleEl = document.getElementById('yt-playlist-title');
    if (titleEl) titleEl.textContent = chapterName || 'Chapter Lectures';

    var countEl = document.getElementById('yt-playlist-count');
    if (countEl) countEl.textContent = (lectures ? lectures.length : 0) + ' Lectures Available';

    if (!lectures || lectures.length === 0) {
      container.innerHTML = '<div style="color:var(--text-muted); font-size:12px; padding:10px;">No lectures in this chapter yet.</div>';
      return;
    }

    lectures.forEach(function(v) {
      var card = document.createElement('div');
      card.className = 'yt-playlist-card' + (curActiveLecture && curActiveLecture.id === v.id ? ' active' : '');
      card.onclick = function() { playPWLecture(v); };
      card.innerHTML = '<div class="yt-thumb-box"><img src="' + v.thumbnail + '" alt="Thumbnail" /><span class="yt-duration-pill">' + v.duration + '</span></div><div class="yt-card-info"><div class="yt-card-title">' + v.title + '</div><div class="yt-card-sub">' + v.faculty + '</div></div>';
      container.appendChild(card);
    });
  }


  function playCustomPWSpeficicURL() {
    var input = document.getElementById('custom-video-url-input');
    if (!input || !input.value.trim()) {
      if (typeof showToast === 'function') showToast('Please enter a video URL first!', 'error');
      return;
    }
    var url = input.value.trim();
    loadSpecificVideoURL(url, "Custom Lecture Stream");
  }

  function loadSpecificVideoURL(url, title) {
    var videoEl = document.getElementById('yt-cloud-video');
    var iframeEl = document.getElementById('yt-iframe-player');
    var overlay = document.getElementById('yt-stream-overlay');
    var titleEl = document.getElementById('yt-active-title');
    var directBtn = document.getElementById('yt-btn-pw-direct');

    if (titleEl) titleEl.textContent = title || "Live PW Video Stream";
    if (overlay) overlay.style.display = 'none';
    if (directBtn) {
      directBtn.href = url;
      directBtn.onclick = null;
      directBtn.target = "_blank";
      directBtn.innerHTML = '<span>🚀 Open in PW Web</span>';
    }

    if (!videoEl || !iframeEl) return;

    if (url.indexOf('youtube.com') !== -1 || url.indexOf('youtu.be') !== -1) {
      videoEl.style.display = 'none';
      iframeEl.style.display = 'block';
      var yId = '';
      if (url.indexOf('v=') !== -1) yId = url.split('v=')[1].split('&')[0];
      else if (url.indexOf('youtu.be/') !== -1) yId = url.split('youtu.be/')[1].split('?')[0];
      iframeEl.src = 'https://www.youtube.com/embed/' + yId + '?autoplay=1';
    } else if (url.indexOf('pw.live/watch') !== -1 || url.indexOf('pw.live/study') !== -1) {
      videoEl.style.display = 'none';
      iframeEl.style.display = 'block';
      iframeEl.src = url;
    } else if (url.indexOf('.mpd') !== -1 || url.indexOf('.m3u8') !== -1) {
      iframeEl.style.display = 'none';
      videoEl.style.display = 'block';
      if (window.dashjs && url.indexOf('.mpd') !== -1) {
        if (pwDashPlayer) pwDashPlayer.reset();
        pwDashPlayer = dashjs.MediaPlayer().create();
        pwDashPlayer.initialize(videoEl, url, true);
      } else {
        videoEl.src = url;
        videoEl.play().catch(function(e){ console.log(e); });
      }
    } else {
      videoEl.style.display = 'none';
      iframeEl.style.display = 'block';
      iframeEl.src = url;
    }

    if (typeof showToast === 'function') {
      showToast('▶ Playing: ' + (title || 'Lecture'), 'success');
    }
  }


  function launchActiveLectureStream() {
    if (!curActiveLecture) return;
    var videoEl = document.getElementById('yt-cloud-video');
    var iframeEl = document.getElementById('yt-iframe-player');
    var overlay = document.getElementById('yt-stream-overlay');

    if (overlay) overlay.style.display = 'none';
    if (videoEl) videoEl.style.display = 'none';
    if (iframeEl) {
      iframeEl.style.display = 'block';
      iframeEl.src = curActiveLecture.pwUrl;
    }
    if (typeof showToast === 'function') {
      showToast('▶ Playing inside website: ' + curActiveLecture.title, 'success');
    }
  }

  function playPWLecture(item) {
    if (!item) return;
    curActiveLecture = item;

    var titleEl = document.getElementById('yt-active-title');
    var overlayTitle = document.getElementById('yt-overlay-title');
    var subjEl = document.getElementById('yt-active-subject');
    var facultyEl = document.getElementById('yt-active-faculty');
    var directBtn = document.getElementById('yt-btn-pw-direct');
    var overlay = document.getElementById('yt-stream-overlay');
    var videoEl = document.getElementById('yt-cloud-video');
    var iframeEl = document.getElementById('yt-iframe-player');

    if (titleEl) titleEl.textContent = item.title;
    if (overlayTitle) overlayTitle.textContent = item.title;
    if (subjEl) subjEl.textContent = item.subject + ' • ' + item.chapter;
    if (facultyEl) facultyEl.textContent = item.faculty;
    if (directBtn) {
      if (item.streamUrl && item.streamUrl.indexOf('youtube.com') !== -1) {
        directBtn.onclick = function(e) {
          e.preventDefault();
          launchActiveLectureStream();
        };
        directBtn.innerHTML = '<span>▶️ Watch Inside Website</span>';
        directBtn.href = '#';
      } else {
        // For PW streams, open directly in a new tab so user can log in without iframe block!
        directBtn.onclick = null;
        directBtn.href = item.pwUrl;
        directBtn.innerHTML = '<span>🔑 PW Login / Open in New Tab</span>';
      }
    }

    if (!videoEl || !iframeEl) return;

    if (item.streamUrl && item.streamUrl.indexOf('youtube.com') !== -1) {
      if (overlay) overlay.style.display = 'none';
      videoEl.style.display = 'none';
      iframeEl.style.display = 'block';
      iframeEl.src = item.streamUrl;
    } else {
      // Show Sleek Overlay first so user can choose to Login/Open in New Tab or Play in Iframe
      if (overlay) {
        overlay.style.display = 'flex';
        overlay.onclick = function() { launchActiveLectureStream(); };
      }
      videoEl.style.display = 'none';
      iframeEl.style.display = 'none';
      iframeEl.src = '';
    }

    document.querySelectorAll('.pw-lecture-item').forEach(function(el) {
      if (el.textContent.indexOf(item.title) !== -1) el.classList.add('active');
      else el.classList.remove('active');
    });
    document.querySelectorAll('.yt-playlist-card').forEach(function(el) {
      if (el.textContent.indexOf(item.title) !== -1) el.classList.add('active');
      else el.classList.remove('active');
    });

    if (typeof showToast === 'function') {
      showToast('▶ ' + item.title, 'success');
    }
  }





  function changePWPlaybackSpeed() {
    var speeds = [1.0, 1.25, 1.5, 2.0];
    var nextIdx = (speeds.indexOf(currentPWSpeed) + 1) % speeds.length;
    currentPWSpeed = speeds[nextIdx];

    var videoEl = document.getElementById('yt-cloud-video');
    if (videoEl) videoEl.playbackRate = currentPWSpeed;
    var lbl = document.getElementById('yt-speed-label');
    if (lbl) lbl.textContent = currentPWSpeed + 'x';
    if (typeof showToast === 'function') showToast('Speed: ' + currentPWSpeed + 'x', 'info');
  }

  function skipPWVideo(deltaSec) {
    var videoEl = document.getElementById('yt-cloud-video');
    if (videoEl) {
      videoEl.currentTime = Math.max(0, videoEl.currentTime + deltaSec);
    }
  }

  function togglePWFullscreen() {
    var wrapper = document.querySelector('.yt-video-wrapper');
    if (wrapper) {
      if (!document.fullscreenElement) {
        wrapper.requestFullscreen().catch(function(err) { alert(err.message); });
      } else {
        document.exitFullscreen();
      }
    }
  }

